INSERT INTO public.product_seo VALUES ('b53286dc-c569-4ab4-ae95-98e8365ed830', '2025-11-10 19:17:45.738353+00', '2025-11-18 07:09:03.524332+00', 'Авт. выкл. Easypact EZC100H - TMD - 100 A - 3 полюса 3Т', 'Schneider Electric EasyPact EZC100H 3P 100A Автоматический Выключатель 30кА', 'Schneider Electric EasyPact EZC100H 3P 100A Avtomatik O''chirgich 30kA', '<p>dwadawd</p>', 'Schneider Electric EasyPact EZC100H 3P 100A трехполюсный автоматический выключатель для защиты от перегрузок и КЗ. Ток 100А, 30кА при 400В. Надёжный выбор для промышленных и коммерческих электросистем.', 'Schneider Electric EasyPact EZC100H 3P 100A 3 qutbli avtomatik o''chirgich elektr zanjirlarini ortiqcha yuklanish va qisqa tutashuvdan himoyalaydi. 100A nominal tok va 400V da 30kA uzish qobiliyatiga ega, sanoat uchun ishonchli tanlov.', 'https://nevel.uz/products/schneider-electric-easypact-ezc100h-3p-100a', 'https://nevel.uz/products/schneider-electric-easypact-ezc100h-3p-100a', NULL, '""', '"Schneider Electric EasyPact EZC100H,EZC100H 3P 100A,автоматический выключатель,MCCB 100А,трехполюсный автомат"', '"Schneider Electric EasyPact EZC100H,EZC100H 3P 100A,avtomatik o''chirgich,MCCB 100A,elektr himoyasi 3 qutbli"', '3a704b89-ab09-412a-a976-7c828ba4ef94', NULL);
