INSERT INTO public.product_seo VALUES ('24553035-157e-44de-a51d-165c1a9b3e29', '2025-11-09 10:22:35.918811+00', '2025-11-17 08:14:27.325936+00', 'Трех позиционный переключатель YCBZ-125 4P 100A', 'Трех позиционный переключатель YCBZ-125 4P 100A', 'CNC YCBZ 4-qutbli yuklama o''chirgichi 400V AC-22A', '', '<p>4-полюсный выключатель нагрузки серии CNC YCBZ предназначен для ручного подключения, отключения и безопасной изоляции электрических цепей низкого напряжения от источника питания. Соответствуя стандарту IEC/EN 60947-3 и категории применения AC-22A, данное устройство обеспечивает надежное переключение смешанных резистивных и индуктивных нагрузок. Прочный корпус и заметная красная рукоятка управления гарантируют долговечность и стабильную работу. Благодаря простоте монтажа и четкой индикации ON/OFF, он идеально подходит для использования в распределительных щитах, промышленных панелях управления, системах автоматизации и других областях, где требуется надежное ручное коммутационное оборудование.</p>', 'CNC YCBZ seriyali 4-qutbli yuklama o''chirgichi past kuchlanishli elektr zanjirlarini qo''lda ulash va uzish, shuningdek, uskunalarni quvvat manbaidan xavfsiz ajratish uchun mo''ljallangan. Ushbu qurilma IEC/EN 60947-3 standarti bo''yicha AC-22A foydalanish toifasiga mos keladi, bu aralash rezistiv va induktiv yuklarni o''z ichiga olgan yuklarni kommutatsiyalash imkonini beradi. Uning mustahkam korpusi va qizil rangli boshqaruv tutqichi uzoq muddatli va ishonchli ishlashni ta''minlaydi. Oson o''rnatish va aniq ON/OFF ko''rsatkichi uni tarqatish panellari, sanoat uskunalarini boshqarish va boshqa avtomatlashtirish tizimlarida xavfsiz elektr izolyatsiyasini ta''minlash uchun ideal tanlovga aylantiradi.', 'https://nevel.uz/products/cnc-ycbz-4-qutbli-yuklama-ochirgichi-400v-ac-22a', 'https://nevel.uz/products/cnc-ycbz-4-qutbli-yuklama-ochirgichi-400v-ac-22a', NULL, '"цфв"', '"цфв"', '""', '0371e4c7-d07b-42e5-9dbe-d179b2a83a31', NULL);
INSERT INTO public.product_seo VALUES ('02e82544-e8cc-4513-95d1-d8f5fd136a9d', '2025-11-15 12:35:25.270336+00', '2025-11-16 18:46:45.366946+00', 'Выключатель нагрузки CNC YCBZ 4-полюсный 400В AC-22A | Защита сети', '111111', '11111', 'Безопасно управляйте электрическими цепями 400В с 4-полюсным выключателем нагрузки CNC YCBZ. Стандарт IEC/EN60947-3, прочный и надежный. Купите сейчас!', '1111', '111', 'https://nevel.uz/products/11111', 'https://nevel.uz/products/11111', NULL, '"выключатель нагрузки CNC YCBZ,4-полюсный рубильник 400В,разъединитель цепей,AC-22A выключатель,промышленный коммутатор,IEC EN60947-3 выключатель,безопасное отключение,модульный выключатель"', '""', '""', '451338d5-3768-4665-a99b-bc2da3e215b3', NULL);
INSERT INTO public.product_seo VALUES ('44ec3b5f-a4ac-4570-8add-9373c2af24fa', '2025-11-17 17:57:17.594576+00', '2025-11-18 06:29:45.109717+00', '1', 'CNC YCIR-16/10 Модульный Контактор, 16А 250В~, DIN-рейка', 'CNC YCIR-16/10 Modular Kontaktor, 16A 250V~, DIN-reyka', '1', 'Модульный контактор CNC YCIR-16/10 для надёжной коммутации нагрузок 16А 250В~. Управление 230В/110В~, установка на DIN-рейку. Удобное решение для систем автоматизации.', 'CNC YCIR-16/10 modular kontaktor. 16A 250V~ yuklarni ishonchli kommutatsiya qilish uchun mo''ljallangan. 230V/110V~ boshqaruv, DIN-reyka o''rnatish uchun ideal. Avtomatlashtirish panellariga mos.', 'https://nevel.uz/products/cnc-ycir-16-10-modular-kontaktor-16a-250v', 'https://nevel.uz/products/cnc-ycir-16-10-modular-kontaktor-16a-250v', NULL, '""', '"cnc ycir-16/10 контактор,модульный контактор 16а,однополюсный контактор,контактор на дин-рейку,контактор 230v 110v управление,контактор для электроцепей,контактор для автоматизации"', '"cnc ycir-16/10 kontaktor,modular kontaktor 16a,bir qutbli kontaktor,din-reyka kontaktor,kontaktor 230v 110v boshqaruv,elektr zanjir kontaktori,avtomatlashtirish uchun kontaktor"', '464af12a-b4e0-47d3-afee-81410e8fb089', NULL);
