INSERT INTO public.product_seo VALUES ('f7b307d1-50a7-4fbd-a9e3-9326a65d8cea', '2025-12-05 09:58:06.574374+00', '2025-12-06 08:35:32.362106+00', 'Schneider Electric EasyPact EZC100H Трехполюсный автоматический выключатель 100А', 'Schneider Electric EasyPact EZC100H Трехполюсный автоматический выключатель 100А', 'Schneider Electric EasyPact EZC100H rusumli 100 amperli uch qutbli avtomatik uzgich', 'Schneider Electric EasyPact EZC100H – надежный трехполюсный автоматический выключатель на 100А. Защита электроцепей до 690В, стандарт IEC 60947-2. Удобное решение для электрощитов.', 'Schneider Electric EasyPact EZC100H – надежный трехполюсный автоматический выключатель на 100А. Защита электроцепей до 690В, стандарт IEC 60947-2. Удобное решение для электрощитов.', 'Schneider Electric EasyPact EZC100H - 100A quvvatli ishonchli uch qutbli avtomatik uzgich hisoblanadi. U 690V gacha bo‘lgan elektr zanjirlarini himoyalaydi va IEC 60947-2 standartiga mos keladi. Elektr shitlari uchun qulay yechim sifatida tavsiya etiladi.', 'https://nevel.uz/products/schneider-electric-easypact-ezc100h-avtomatik-ochirgich', 'https://nevel.uz/products/schneider-electric-easypact-ezc100h-avtomatik-ochirgich', NULL, '"Schneider Electric EasyPact EZC100H,автоматический выключатель 100А,трехполюсный автомат,защита электроцепей,модульный выключатель"', '"Schneider Electric EasyPact EZC100H,автоматический выключатель 100А,трехполюсный автомат,защита электроцепей,модульный выключатель"', '"Schneider Electric EasyPact EZC100H,avtomatik o''chirgich 100A,3 qutbli avtomat,elektr paneli himoyasi,zanjir to''xtatgich"', '491d209e-88ad-4c78-a594-30bc06176e0b', NULL);
