INSERT INTO public.product_seo VALUES ('6db4a5bf-c0f2-4c6a-8b4b-85bf25aa81ee', '2025-11-23 09:22:41.448501+00', '2025-12-11 06:37:40.069138+00', 'Автоматический выключатель БАЙПАС DZ47 HS 1P 63A', 'Автоматический выключатель БАЙПАС DZ47 HS 1P 63A', 'DZ47 HS 1P 63A BAYPAS avtomatik o‘chirg‘ichi', '<p>Автоматический выключатель БАЙПАС DZ47 HS 1P 63A — это надежное коммутационное устройство, предназначенное для защиты и управления электрическими цепями. Он обеспечивает возможность оперативного включения и отключения нагрузок в электрических сетях, а также переключения байпасных схем при необходимости. Устройство рассчитано на монтаж на стандартную DIN-рейку, что гарантирует легкую установку и интеграцию в существующие электрические распределительные щиты. Его высокая стабильность работы и долговечность обеспечивают бесперебойную и безопасную эксплуатацию электросистем на промышленных, бытовых и административных объектах.</p>', '<p>Автоматический выключатель БАЙПАС DZ47 HS 1P 63A — это надежное коммутационное устройство, предназначенное для защиты и управления электрическими цепями. Он обеспечивает возможность оперативного включения и отключения нагрузок в электрических сетях, а также переключения байпасных схем при необходимости. Устройство рассчитано на монтаж на стандартную DIN-рейку, что гарантирует легкую установку и интеграцию в существующие электрические распределительные щиты. Его высокая стабильность работы и долговечность обеспечивают бесперебойную и безопасную эксплуатацию электросистем на промышленных, бытовых и административных объектах.</p>', 'BAYPAS DZ47 HS 1P 63A avtomatik uzgichi elektr zanjirlarini himoyalash va boshqarish uchun mo‘ljallangan ishonchli kommutatsiya qurilmasi hisoblanadi. U elektr tarmoqlaridagi yuklamalarni tezkor ravishda ulash va uzish, shuningdek, zarur hollarda baypas sxemalarini almashtirish imkonini beradi. Qurilma standart DIN-reykaga o‘rnatilishi ko‘zda tutilgan bo‘lib, bu mavjud elektr taqsimlash shchitlariga oson o‘rnatish va ularni integratsiyalashni ta’minlaydi. Uning yuqori barqarorlik bilan ishlashi va uzoq muddat xizmat qilishi sanoat, maishiy va ma’muriy obyektlardagi elektr tizimlarining uzluksiz va xavfsiz faoliyat yuritishini kafolatlaydi.', '', 'https://nevel.uz/products/testovyy-url1', 'https://nevel.uz/products/test-urluz', '""', '""', '""', '58d1f20c-53d0-44a0-a0e6-6f8f55595cee', '2dd88510-b73c-4660-b6da-21c307b8544b');
INSERT INTO public.product_seo VALUES ('2ce3e528-295c-4836-926e-a2a54b5074bc', '2025-12-09 06:10:15.355813+00', '2025-12-11 06:59:18.320536+00', 'Inductive Proximity Sensor M18 — индуктивный датчик, M18 цилиндрический', 'Inductive Proximity Sensor M18 — индуктивный датчик, M18 цилиндрический', 'M18 induktiv yaqinlik sensori - M18 silindrsimon shakldagi induktiv datchik', 'Inductive Proximity Sensor M18 — индуктивный датчик приближения в металлическом корпусе, цилиндрический M18. Подходит для автоматизации и конвейерных систем.', 'Inductive Proximity Sensor M18 — индуктивный датчик приближения в металлическом корпусе, цилиндрический M18. Подходит для автоматизации и конвейерных систем.', 'Inductive Proximity Sensor M18 - metall korpusli, silindrsimon M18 shaklidagi induktiv yaqinlashish datchigi. U avtomatlashtirish va konveyer tizimlariga mosdir.', '', 'https://nevel.uz/products/inductive-proximity-sensor-m18', 'https://nevel.uz/products/inductive-proximity-sensor-m18', '"Inductive Proximity Sensor M18,индуктивный датчик,датчик приближения,датчик M18,металлический датчик,датчик для автоматизации,цилиндрический датчик"', '"Inductive Proximity Sensor M18,индуктивный датчик,датчик приближения,датчик M18,металлический датчик,датчик для автоматизации,цилиндрический датчик"', '"Inductive Proximity Sensor M18,induktiv sensor,yaqinlik sensori,M18 sensor,metall sensor,avtomatlashtirish sensori,silindrik sensor"', 'dbf3a60a-6b9e-422f-bf68-acacf139bcbf', 'f52e11e1-706f-4428-b2f0-dbf7c2e050d8');
INSERT INTO public.product_seo VALUES ('3e62627f-2c90-4479-b1e3-86870f493506', '2025-12-09 05:50:13.239356+00', '2025-12-11 10:51:05.690086+00', 'Индуктивный датчик M12 — сенсор приближения, 3-проводной', 'Индуктивный датчик M12 — сенсор приближения, 3-проводной', 'M12 induktiv datchigi - yaqinlashishni aniqlovchi 3 simli sensor', 'Индуктивный датчик M12 — надёжный 3-проводной сенсор для бесконтактного обнаружения металлических объектов. Подходит для систем автоматизации и конвейеров, удобное решение.', 'Индуктивный датчик M12 — надёжный 3-проводной сенсор для бесконтактного обнаружения металлических объектов. Подходит для систем автоматизации и конвейеров, удобное решение.', 'M12 induktiv datchigi - metall ob’ektlarni kontaktsiz aniqlash uchun ishonchli uch simli sensordir. U avtomatlashtirish tizimlari va konveyerlar uchun mos bo‘lib, qulay yechim hisoblanadi.', 'https://nevel.uz/products/lj8a3-2-zby-no-pnp-6-36vdc-datchik-induktivnyy-m8-distantsiya-2-mm-trekhprovodnoy', 'https://nevel.uz/products/induktivnyy-datchik-m12', 'https://nevel.uz/products/induktiv-sensor-m12', '"индуктивный датчик m12,датчик приближения,3-проводной сенсор,датчик обнаружения металла,датчик для автоматизации,цилиндрический датчик"', '"индуктивный датчик m12,датчик приближения,3-проводной сенсор,датчик обнаружения металла,датчик для автоматизации,цилиндрический датчик"', '"induktiv sensor m12,yaqinlik datchigi,3 simli sensor,metall aniqlash datchigi,avtomatlashtirish datchigi,silindrsimon sensor"', '86c06014-1c42-43fe-ab89-69d99701a509', 'e1cec014-f7d0-4511-9da4-d744ec1d66a1');
