INSERT INTO public.products VALUES ('d24b0d79-31c5-4e05-b97b-24ca82f46ad1', '2025-12-07 10:16:06.897791+00', '2025-12-07 10:18:34.574301+00', NULL, '', 'CNC YCBZ', 'CNC YCBZ', 'CNC YCBZ', '<p>CNC YCBZ – это модульный выключатель-разъединитель, предназначенный для ручного безопасного включения, отключения и изоляции электрических цепей. Это 4-полюсное устройство с номинальным напряжением 400В и категорией применения AC-22A идеально подходит для коммутации резистивных и слабоиндуктивных нагрузок. Оно легко монтируется на DIN-рейку и обеспечивает быстрое подключение через надежные винтовые клеммы. Конструкция с белым корпусом и красными рычагами гарантирует надежную и стабильную работу в электрических распределительных щитах и панелях управления, повышая безопасность и контроль в низковольтных электроустановках.</p>', '<p>CNC YCBZ – это модульный выключатель-разъединитель, предназначенный для ручного безопасного включения, отключения и изоляции электрических цепей. Это 4-полюсное устройство с номинальным напряжением 400В и категорией применения AC-22A идеально подходит для коммутации резистивных и слабоиндуктивных нагрузок. Оно легко монтируется на DIN-рейку и обеспечивает быстрое подключение через надежные винтовые клеммы. Конструкция с белым корпусом и красными рычагами гарантирует надежную и стабильную работу в электрических распределительных щитах и панелях управления, повышая безопасность и контроль в низковольтных электроустановках.</p>', 'CNC YCBZ - elektr zanjirlarini qo‘lda xavfsiz ulash, uzish va izolyatsiya qilish uchun mo‘ljallangan modulli o‘chirgich-ajratgichdir. 400V nominal kuchlanishga va AC-22A qo‘llanilish toifasiga ega bo‘lgan ushbu 4 qutbli qurilma rezistiv va kuchsiz induktiv yuklamalarni kommutatsiya qilish uchun juda qulay hisoblanadi. U DIN-reykaga osonlik bilan o‘rnatiladi va ishonchli vintli klemmalar orqali tez ulanishni ta’minlaydi. Oq korpus va qizil richaglardan iborat konstruktsiya elektr taqsimlash shchitlari va boshqaruv panellarida ishonchli hamda barqaror ishlashni kafolatlaydi, shuningdek, past kuchlanishli elektr qurilmalarida xavfsizlik va nazoratni oshiradi.', NULL, NULL, NULL, NULL, NULL, NULL, false, 0.00, 0.00, 0, 'published', false, '3dd065bb-897d-4e64-b0de-f98b7e432ced', NULL, NULL, false, false, NULL);
