INSERT INTO public.products VALUES ('0a5e9a9f-ea7d-40e1-a7df-a70acc514efc', '2025-12-05 10:29:29.795298+00', '2026-03-01 07:40:15.22211+00', 'dc1a81c6-9ded-11f0-a14e-005056b88cb9', '6476', 'LJ38A4-25-Z/CX NO+NC NPN 6-36VDC Датчик индуктивный M38 дистанция 25 мм четырехпроводной', 'LJ38A4-25-Z/CX NO+NC NPN 6-36VDC Датчик индуктивный M38 дистанция 25 мм четырехпроводной', '', '', '', '', 'induktivnyy-datchik-priblizheniya-j3ba4-20', 'induktivnyy-datchik-priblizheniya-j3ba4-20', 'induktiv-yaqinlik-datchigi-j3ba4-20', '2600100030617', '08517002017000000', '1350310', false, 125000.00, 0.00, 10, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '22e7d30c-2557-42c0-97e3-f102e2e34cc3', true, false, NULL);
INSERT INTO public.products VALUES ('e2ee1c1f-8edd-42f3-abd7-10c9016c03c7', '2026-02-14 10:16:33.896186+00', '2026-03-01 07:40:15.398373+00', '2dfc4ff8-c458-11f0-a150-005056b88cb9', '6588', 'HO-12N3 / HX-DGS-12N3 NPN NO+NC, кольцевой индуктивный датчик, внутренний диаметр 12 мм, питание 10–', 'HO-12N3 / HX-DGS-12N3 NPN NO+NC, кольцевой индуктивный датчик, внутренний диаметр 12 мм, питание 10–', 'HO-12N3 / HX-DGS-12N3 NPN NO+NC, halqasimon induktiv sensorli datchik, ichki diametri 12 mm bo‘lgan, 10- volt kuchlanish bilan ta’minlanadigan', '<p>HO-12N3 / HX-DGS-12N3 NPN NO+NC, кольцевой индуктивный датчик, внутренний диаметр 12 мм, питание 10– — это кольцевой индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов в промышленных системах автоматизации. Датчик имеет внутренний диаметр 12 мм, выход NPN NC+NC и рассчитан на питание от 10 В. Он обеспечивает точное и надежное обнаружение металлических деталей на конвейерных линиях, в упаковочном оборудовании и других производственных процессах. Прочный корпус и стабильная работа гарантируют высокую надежность и долговечность. Легкость монтажа и интеграции в существующие системы автоматизации делает его универсальным решением для различных промышленных задач.</p>', '<p>HO-12N3 / HX-DGS-12N3 NPN NO+NC, кольцевой индуктивный датчик, внутренний диаметр 12 мм, питание 10– — это кольцевой индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов в промышленных системах автоматизации. Датчик имеет внутренний диаметр 12 мм, выход NPN NC+NC и рассчитан на питание от 10 В. Он обеспечивает точное и надежное обнаружение металлических деталей на конвейерных линиях, в упаковочном оборудовании и других производственных процессах. Прочный корпус и стабильная работа гарантируют высокую надежность и долговечность. Легкость монтажа и интеграции в существующие системы автоматизации делает его универсальным решением для различных промышленных задач.</p>', '<p>HO-12N3 / HX-DGS-12N3 NPN NO+NC - bu ichki diametri 12 mm bo‘lgan halqasimon induktiv datchik bo‘lib, 10 V kuchlanish bilan ishlaydi va sanoat avtomatlashtirish tizimlarida metall buyumlarni kontaktsiz aniqlash uchun mo‘ljallangan. Datchik NPN NC+NC chiqishiga ega. U konveyer liniyalari, qadoqlash uskunalari va boshqa ishlab chiqarish jarayonlarida metall qismlarni aniq va ishonchli tarzda aniqlab beradi. Mustahkam korpusi va barqaror ishlashi uning yuqori darajada ishonchli va uzoq muddat xizmat qilishini ta’minlaydi. O‘rnatish va mavjud avtomatlashtirish tizimlariga oson integratsiya qilish imkoniyati uni turli sanoat vazifalari uchun universal yechimga aylantiradi.</p>', 'ho-12n3-hx-dgs-12n3-npn-no-nc-koltsevoy-induktivnyy-datchik-vnutrenniy-diametr-12-mm-pitaniye-10', 'ho-12n3-hx-dgs-12n3-npn-no-nc-koltsevoy-induktivnyy-datchik-vnutrenniy-diametr-12-mm-pitaniye-10', 'ho-12n3-hx-dgs-12n3-npn-no-nc-koltsevoy-induktivnyy-datchik-vnutrenniy-diametr-12-mm-pitaniye-10', '2600100031737', '08517002017000000', '1350310', false, 115000.00, 0.00, 5, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '2dcfe231-bb9d-4b84-86b4-b92100aebbb6', true, true, NULL);
