INSERT INTO public.products VALUES ('f9a0c6fb-e71f-442d-bcd5-800052930265', '2025-11-03 12:21:21.848331+00', '2025-11-23 18:44:06.811116+00', '4a060dcd-3cfa-11ef-a139-005056b88cb9', '4960', 'CS AR-05V024, Модуль реле безопасности PIZZATO ELETTRICA', 'CS AR-05V024, Модуль реле безопасности PIZZATO ELETTRICA', 'Pizzato Xavfsizlik releysi 24V AC/DC', '<p>Данное реле безопасности Pizzato 24В AC/DC предназначено для мониторинга функций безопасности, таких как аварийные выключатели, защитные ограждения и световые завесы, в промышленных условиях. Оно работает от универсального источника питания 24В переменного или постоянного тока (50-60 Гц) и оснащено множеством нормально разомкнутых (NO) безопасных выходных контактов, рассчитанных на 230В 3А для AC-15 и 24В 4А для DC-13. Соответствуя строгим стандартам EN ISO 13849 PL e Cat. 4 и EN 62061 SIL CL 3, это реле безопасности Pizzato обеспечивает высочайший уровень надежности и максимальную безопасность для персонала и оборудования. Легко устанавливаемое на DIN-рейку, оно также имеет светодиодные индикаторы PWR, CH1, CH2 для быстрой диагностики состояния, что делает его идеальным выбором для систем промышленной автоматизации, безопасности машин и робототехники.</p>', '<p>Данное реле безопасности Pizzato 24В AC/DC предназначено для мониторинга функций безопасности, таких как аварийные выключатели, защитные ограждения и световые завесы, в промышленных условиях. Оно работает от универсального источника питания 24В переменного или постоянного тока (50-60 Гц) и оснащено множеством нормально разомкнутых (NO) безопасных выходных контактов, рассчитанных на 230В 3А для AC-15 и 24В 4А для DC-13. Соответствуя строгим стандартам EN ISO 13849 PL e Cat. 4 и EN 62061 SIL CL 3, это реле безопасности Pizzato обеспечивает высочайший уровень надежности и максимальную безопасность для персонала и оборудования. Легко устанавливаемое на DIN-рейку, оно также имеет светодиодные индикаторы PWR, CH1, CH2 для быстрой диагностики состояния, что делает его идеальным выбором для систем промышленной автоматизации, безопасности машин и робототехники.</p>', 'Bu Pizzato xavfsizlik releysi 24V AC/DC sanoat muhitida favqulodda to''xtatish tugmalari, xavfsizlik eshiklari va boshqa himoya moslamalarini nazorat qilish uchun mo''ljallangan. U 24V AC/DC (50-60 Hz) universal kuchlanishda ishlaydi va bir nechta normal ochiq (NO) xavfsizlik chiqish kontaktlariga ega, ularning har biri AC-15 uchun 230V 3A va DC-13 uchun 24V 4A quvvatga ega. EN ISO 13849 PL e Cat. 4 va EN 62061 SIL CL 3 standartlariga muvofiq ishlab chiqilgan ushbu Pizzato xavfsizlik releysi yuqori ishonchlilik va xodimlar hamda uskunalar uchun maksimal xavfsizlikni ta''minlaydi. DIN reyiga o''rnatilishi oson bo''lib, PWR, CH1, CH2 indikatorlari tufayli tez diagnostika qilish imkonini beradi, bu esa uni sanoat avtomatlashtirish, mashinalar xavfsizligi va robototexnika tizimlari uchun ideal tanlovga aylantiradi.', NULL, NULL, 'pizzato-xavfsizlik-releysi-24v-acdc', '8018851091681', '08536007013000525', '1730066', false, 2323400.00, 0.00, 0, 'pending', false, NULL, NULL, '0592e97f-7d22-407a-a2ef-015ba3bb925c', true, true, NULL);
INSERT INTO public.products VALUES ('676c1a99-73b2-4bf1-a30f-613c440a14de', '2025-12-12 12:00:59.667567+00', '2026-03-01 07:40:14.76616+00', 'f922e30d-b370-11ee-a12b-005056b88cb9', '4352', 'PR30-10AO NO 90-250VAC Датчик индуктивный M30 дистанция 10 мм двухпроводной', 'PR30-10AO NO 90-250VAC Датчик индуктивный M30 дистанция 10 мм двухпроводной', 'PR30-10AO NO 90-250VAC M30 induktiv sensorli, 10 mm masofali, ikki simli datchik', '<p>PR30-10AO NO 90-250VAC Датчик индуктивный M30 дистанция 10 мм двухпроводной — это надежный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Этот датчик в прочном цилиндрическом корпусе M30 обеспечивает стабильное определение объектов на расстоянии 10 мм и работает в широком диапазоне напряжения 90-250VAC. Он идеально подходит для использования в автоматизированных линиях, на конвейерах и в машиностроении для контроля положения и присутствия объектов. Двухпроводное подключение обеспечивает простоту монтажа и интеграции в системы автоматизации, гарантируя долговременную стабильность и надежность работы.</p>', '<p>PR30-10AO NO 90-250VAC Датчик индуктивный M30 дистанция 10 мм двухпроводной — это надежный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Этот датчик в прочном цилиндрическом корпусе M30 обеспечивает стабильное определение объектов на расстоянии 10 мм и работает в широком диапазоне напряжения 90-250VAC. Он идеально подходит для использования в автоматизированных линиях, на конвейерах и в машиностроении для контроля положения и присутствия объектов. Двухпроводное подключение обеспечивает простоту монтажа и интеграции в системы автоматизации, гарантируя долговременную стабильность и надежность работы.</p>', 'PR30-10AO NO 90-250VAC M30 induktiv datchigi 10 mm masofali ikki simli - bu metall obyektlarni kontaktsiz aniqlash uchun mo‘ljallangan ishonchli qurilma. M30 mustahkam silindrsimon korpusga ega bo‘lgan ushbu datchik 10 mm masofadagi obyektlarni barqaror aniqlay oladi va 90-250VAC keng kuchlanish oralig‘ida ishlaydi. U avtomatlashtirilgan liniyalarda, konveyerlarda va mashinasozlikda obyektlarning joylashuvi va mavjudligini nazorat qilish uchun juda qulay. Ikki simli ulanish o‘rnatish jarayonini osonlashtiradi va avtomatlashtirish tizimlariga integratsiya qilishni soddalash bilan birga, uzoq muddatli barqarorlik va ishonchlilikni kafolatlaydi.', 'pr30-10ao-no-90-250vac-datchik-induktivnyy-m30-distantsiya-10-mm-dvukhprovodnoy', 'pr30-10ao-no-90-250vac-datchik-induktivnyy-m30-distantsiya-10-mm-dvukhprovodnoy', 'pr30-10ao-no-90-250vac-datchik-induktivnyy-m30-distantsiya-10-mm-dvukhprovodnoy', '2600100001075', '08517002017000000', '1350310', false, 108000.00, 0.00, 31, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, 'ff528dc6-5c01-4819-af2b-2252f2a7dfb9', true, true, NULL);
INSERT INTO public.products VALUES ('d15f487f-b85a-400b-abc1-fbe52c843018', '2026-02-14 09:41:25.158241+00', '2026-03-01 07:40:14.804621+00', 'f81956b3-b373-11ee-a12b-005056b88cb9', '4373', 'GKB-M0524NA NPN NO 10–30VDC, индуктивный датчик прямоугольный, дистанция 5 мм', 'GKB-M0524NA NPN NO 10–30VDC, индуктивный датчик прямоугольный, дистанция 5 мм', 'GKB-M0524NA NPN NO 10-30VDC, to‘g‘ri burchakli induktiv sezgich, sezish masofasi 5 mm', '<p>GKB-M0524NA NPN NO 10–30VDC, индуктивный датчик прямоугольный, дистанция 5 мм — это надежный сенсор, предназначенный для бесконтактного обнаружения металлических объектов. Этот прямоугольный индуктивный датчик работает от напряжения 10 до 30 В постоянного тока, обеспечивая точное срабатывание на расстоянии до 5 мм. Он широко применяется в автоматизированных производственных линиях, на конвейерах и в системах определения положения механических частей. Легкость монтажа, высокая надежность и стабильность работы делают его незаменимым решением для различных задач промышленной автоматизации.</p>', '<p>GKB-M0524NA NPN NO 10–30VDC, индуктивный датчик прямоугольный, дистанция 5 мм — это надежный сенсор, предназначенный для бесконтактного обнаружения металлических объектов. Этот прямоугольный индуктивный датчик работает от напряжения 10 до 30 В постоянного тока, обеспечивая точное срабатывание на расстоянии до 5 мм. Он широко применяется в автоматизированных производственных линиях, на конвейерах и в системах определения положения механических частей. Легкость монтажа, высокая надежность и стабильность работы делают его незаменимым решением для различных задач промышленной автоматизации.</p>', 'GKB-M0524NA NPN NO 10-30VDC, to‘g‘ri burchakli induktiv datchik, masofasi 5 mm - bu metall obyektlarni kontaktsiz aniqlash uchun mo‘ljallangan ishonchli sensordir. Ushbu to‘g‘ri burchakli induktiv datchik 10 voltdan 30 voltgacha bo‘lgan o‘zgarmas tok kuchlanishida ishlaydi va 5 millimetrgacha masofada aniq ishlashni ta’minlaydi. U avtomatlashtirilgan ishlab chiqarish liniyalarida, konveyerlarda va mexanik qismlarning holatini aniqlash tizimlarida keng qo‘llaniladi. O‘rnatishning osonligi, yuqori ishonchliligi va ishlashining barqarorligi uni sanoat avtomatlashtirish sohasidagi turli vazifalar uchun almashtirib bo‘lmaydigan yechimga aylantiradi.', 'gkb-m0524na-npn-no-10-30vdc-induktivnyy-datchik-pryamougolnyy-distantsiya-5-mm', 'gkb-m0524na-npn-no-10-30vdc-induktivnyy-datchik-pryamougolnyy-distantsiya-5-mm', 'gkb-m0524na-npn-no-10-30vdc-induktivnyy-datchik-pryamougolnyy-distantsiya-5-mm', '2600100002171', '08517002017000000', '1350310', false, 128600.00, 0.00, 32, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '2354690e-f7eb-47d3-9103-6ca8bea347f0', true, true, NULL);
