INSERT INTO public.products VALUES ('464af12a-b4e0-47d3-afee-81410e8fb089', '2025-11-03 12:21:17.092542+00', '2025-12-04 09:26:11.557822+00', 'a32f587c-a121-11ed-a805-bb22e695b629', '3475', 'Импульсное реле YCIR 16/10 1P AC220V', 'Импульсное реле YCIR 16/10 1P AC220V', 'CNC YCIR-16/10 Modular Kontaktor, 16A 250V~', '<p>Модульный контактор CNC YCIR-16/10 представляет собой компактное устройство, предназначенное для дистанционного управления и коммутации электрических цепей. Он обеспечивает надежное включение и отключение нагрузок до 16А при напряжении до 250В~ в системах переменного тока. Устанавливается на DIN-рейку, что упрощает монтаж в стандартные распределительные щитки. Управление контактором осуществляется через клеммы A1 и A2 с возможностью выбора напряжения управляющей катушки 230В~ или 110В~, что повышает его универсальность. Данный тип контакторов широко применяется в щитах автоматизации, для управления освещением, пуска электродвигателей и в системах отопления, обеспечивая стабильную и безопасную работу оборудования.</p>', '<p>Модульный контактор CNC YCIR-16/10 представляет собой компактное устройство, предназначенное для дистанционного управления и коммутации электрических цепей. Он обеспечивает надежное включение и отключение нагрузок до 16А при напряжении до 250В~ в системах переменного тока. Устанавливается на DIN-рейку, что упрощает монтаж в стандартные распределительные щитки. Управление контактором осуществляется через клеммы A1 и A2 с возможностью выбора напряжения управляющей катушки 230В~ или 110В~, что повышает его универсальность. Данный тип контакторов широко применяется в щитах автоматизации, для управления освещением, пуска электродвигателей и в системах отопления, обеспечивая стабильную и безопасную работу оборудования.</p>', 'CNC YCIR-16/10 modular kontaktor – bu elektr zanjirlarini masofadan boshqarish va kommutatsiya qilish uchun mo''ljallangan ixcham qurilmadir. U AC tizimlarida 16A va 250V~ gacha bo''lgan yuklarni ishonchli ravishda yoqish va o''chirishni ta''minlaydi. DIN reykaga o''rnatish uchun mo''ljallangan bo''lib, uni o''rnatish juda oson. Boshqaruv terminallari A1 va A2 orqali 230V~ yoki 110V~ kuchlanish bilan boshqariladi, bu esa turli elektr ta''minoti sharoitlarida foydalanish imkonini beradi. Ushbu kontaktorlar avtomatlashtirish panellarida, yorug''lik tizimlarini boshqarishda, elektr motorlarni ishga tushirishda va isitish tizimlarida keng qo''llaniladi, tizimlarning xavfsiz va barqaror ishlashini ta''minlaydi.', NULL, NULL, 'cnc-ycir-16-10-modular-kontaktor-16a-250v', '2600100031126', '08536007013000003', '1377283', false, 79300.00, 0.00, 16, 'published', false, NULL, NULL, '3cac6bec-9e7b-4d07-ae48-0669adb4a9c7', true, true, NULL);
