INSERT INTO public.products VALUES ('1c99dc8e-e733-4123-ac6e-45ea36b8fcbe', '2025-12-12 10:11:53.883874+00', '2026-02-14 07:03:56.692685+00', 'fa91f5e6-d742-11f0-a152-005056b88cb9', '6650', 'SDR-240-24 MEAN WELL - блок питания, 24В, 10A, для монтажа на DIN-рейку', 'SDR-240-24 MEAN WELL - блок питания, 24В, 10A, для монтажа на DIN-рейку', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2600100032130', '08504003009000007', '1726381', false, 571400.00, 0.00, 10, 'published', false, NULL, NULL, NULL, true, false, NULL);
INSERT INTO public.products VALUES ('baa84101-8f2c-4af5-ba1c-c5aa269504b0', '2026-02-14 10:16:42.052591+00', '2026-03-01 07:40:15.48894+00', '4a34d157-c458-11f0-a150-005056b88cb9', '6591', 'HO-30P3 / HX-DGS-30P3 PNP NO+NC, кольцевой индуктивный датчик, внутренний диаметр 30 мм, питание 10–', 'HO-30P3 / HX-DGS-30P3 PNP NO+NC, кольцевой индуктивный датчик, внутренний диаметр 30 мм, питание 10–', 'HO-30P3 / HX-DGS-30P3 PNP NO+NC, halqasimon induktiv sezgich, ichki diametri 30 mm bo‘lgan, 10- volt kuchlanish bilan ta’minlanadigan', 'HO-30P3 / HX-DGS-30P3 PNP NO+NC, кольцевой индуктивный датчик, внутренний диаметр 30 мм, питание 10– — это высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов, проходящих через его кольцевое отверстие. Он оснащен выходом PNP с нормально открытым (NO) и нормально закрытым (NC) контактами, что обеспечивает гибкость подключения к различным системам управления. Благодаря своему кольцевому форм-фактору с внутренним диаметром 30 мм, датчик идеально подходит для контроля наличия, положения или подсчета мелких металлических деталей, проводов или стержней. Датчик отличается высокой надежностью, устойчивостью к промышленным условиям и простотой интеграции в существующие системы автоматизации. Применяется на конвейерных линиях, в упаковочном оборудовании, машиностроении и в системах подсчета продукции для эффективного управления производственными процессами.', 'HO-30P3 / HX-DGS-30P3 PNP NO+NC, кольцевой индуктивный датчик, внутренний диаметр 30 мм, питание 10– — это высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов, проходящих через его кольцевое отверстие. Он оснащен выходом PNP с нормально открытым (NO) и нормально закрытым (NC) контактами, что обеспечивает гибкость подключения к различным системам управления. Благодаря своему кольцевому форм-фактору с внутренним диаметром 30 мм, датчик идеально подходит для контроля наличия, положения или подсчета мелких металлических деталей, проводов или стержней. Датчик отличается высокой надежностью, устойчивостью к промышленным условиям и простотой интеграции в существующие системы автоматизации. Применяется на конвейерных линиях, в упаковочном оборудовании, машиностроении и в системах подсчета продукции для эффективного управления производственными процессами.', '<p>HO-30P3 / HX-DGS-30P3 PNP NO+NC - bu ichki diametri 30 mm bo‘lgan halqali induktiv datchik bo‘lib, 10-30 V kuchlanish bilan ishlaydi. U o‘zining halqasimon teshigidan o‘tayotgan metall jismlarni kontaktsiz aniqlash uchun mo‘ljallangan yuqori aniqlikdagi qurilmadir. Datchik normal ochiq (NO) va normal yopiq (NC) kontaktli PNP chiqishi bilan jihozlangan, bu esa turli xil boshqaruv tizimlariga moslashuvchan ulanish imkonini beradi. Uning 30 mm ichki diametrli halqasimon shakli tufayli, kichik metall qismlar, simlar yoki sterjenlarning mavjudligi, joylashuvi yoki sonini nazorat qilishda juda qulaydir. Bu datchik yuqori ishonchlilik, sanoat sharoitlariga bardoshlilik va mavjud avtomatlashtirish tizimlariga oson integratsiyalashuvi bilan ajralib turadi. U ishlab chiqarish jarayonlarini samarali boshqarish maqsadida konveyer liniyalarida, qadoqlash uskunalarida, mashinasozlikda va mahsulotlarni hisoblash tizimlarida keng qo‘llaniladi.</p>', 'ho-30p3-hx-dgs-30p3-pnp-no-nc-koltsevoy-induktivnyy-datchik-vnutrenniy-diametr-30-mm-pitaniye-10', 'ho-30p3-hx-dgs-30p3-pnp-no-nc-koltsevoy-induktivnyy-datchik-vnutrenniy-diametr-30-mm-pitaniye-10', 'ho-30p3-hx-dgs-30p3-pnp-no-nc-koltsevoy-induktivnyy-datchik-vnutrenniy-diametr-30-mm-pitaniye-10', '2600100031768', '08517002017000000', '1350310', false, 115000.00, 0.00, 5, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '2dcfe231-bb9d-4b84-86b4-b92100aebbb6', true, true, NULL);
INSERT INTO public.products VALUES ('58d1f20c-53d0-44a0-a0e6-6f8f55595cee', '2025-11-03 12:21:20.819558+00', '2026-02-19 08:36:05.946157+00', '0e293507-eda6-11ea-a7a5-e117a061f846', '718', 'Автоматический выключатель БАЙПАС DZ47 HS 1P 63A', 'Автоматический выключатель БАЙПАС DZ47 HS 1P 63A', 'DZ47 HS 1P 63A avtomatik o‘chiruvchi BAYPAS', '<p>Автоматический выключатель БАЙПАС DZ47 HS 1P 63A — это надежное коммутационное устройство, предназначенное для защиты и оперативного управления электрическими цепями. Он обеспечивает возможность включения и отключения нагрузок, а также переключения байпасных схем в сетях переменного тока до 400В. Данное устройство подходит для коммутации смешанных активно-индуктивных нагрузок. Выключатель рассчитан на монтаж на стандартную DIN-рейку, что гарантирует легкую установку и интеграцию в существующие электрические распределительные щиты. Его высокая стабильность работы и долговечность обеспечивают бесперебойную и безопасную эксплуатацию электросистем на промышленных, бытовых и административных объектах….</p>', '<p>Автоматический выключатель БАЙПАС DZ47 HS 1P 63A — это надежное коммутационное устройство, предназначенное для защиты и оперативного управления электрическими цепями. Он обеспечивает возможность включения и отключения нагрузок, а также переключения байпасных схем в сетях переменного тока до 400В. Данное устройство подходит для коммутации смешанных активно-индуктивных нагрузок. Выключатель рассчитан на монтаж на стандартную DIN-рейку, что гарантирует легкую установку и интеграцию в существующие электрические распределительные щиты. Его высокая стабильность работы и долговечность обеспечивают бесперебойную и безопасную эксплуатацию электросистем на промышленных, бытовых и административных объектах….</p>', 'BAYPAS DZ47 HS 1P 63A avtomatik o‘chirgichi ishonchli kommutatsiya qurilmasi bo‘lib, elektr zanjirlarini himoyalash va tezkor boshqarish uchun mo‘ljallangan. U 400 V gacha bo‘lgan o‘zgaruvchan tok tarmoqlarida yuklamalarni ulash va uzish, shuningdek, baypas sxemalarini almashtirish imkoniyatini ta’minlaydi. Ushbu qurilma aralash aktiv-induktiv yuklamalarni kommutatsiyalash uchun mos keladi. O‘chirgich standart DIN-reykaga o‘rnatishga mo‘ljallangan bo‘lib, bu mavjud elektr taqsimlash shchitlariga oson o‘rnatish va moslashtirishni kafolatlaydi. Uning yuqori barqarorlik bilan ishlashi va uzoq muddat xizmat qilishi sanoat, maishiy va ma’muriy obyektlardagi elektr tizimlarining uzluksiz va xavfsiz ishlashini ta’minlaydi.', 'testovyy-url1', 'testovyy-url1', 'test-urluz', NULL, '08536001037000001', '1520552', false, 49200.00, 0.00, 0, 'published', false, NULL, NULL, NULL, true, false, NULL);
