INSERT INTO public.products VALUES ('f1afc778-7455-47bd-a2bb-29e53a90f8ca', '2025-12-09 05:37:39.092096+00', '2026-03-01 07:40:15.93277+00', 'b80b7dac-97c3-11eb-a7ce-68ecc5c3e82a', '1650', 'LJ8A3-2-Z/BX NO NPN 6-36VDC Датчик индуктивный M8 дистанция 2 мм трехпроводной', 'LJ8A3-2-Z/BX NO NPN 6-36VDC Датчик индуктивный M8 дистанция 2 мм трехпроводной', 'LJ8A3-2-Z/BX NO NPN 6-36VDC induksion sensor, M8 o‘lchamli, 2 mm masofali, uch simli', '<p>LJ8A3-2-Z/BX NO NPN 6-36VDC Датчик индуктивный M8 дистанция 2 мм трехпроводной — высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения присутствия и положения металлических объектов. Этот датчик выполнен в цилиндрическом металлическом корпусе M8 с резьбовым креплением для удобной установки. Он работает в диапазоне напряжения 6-36В постоянного тока и имеет трехпроводное подключение (тип NPN NO). Благодаря индуктивному принципу, он обеспечивает высокую надежность, долговечность и стабильность работы, что упрощает его интеграцию в системы автоматизации. Датчик широко применяется на автоматизированных линиях, конвейерах и в различных механизмах для точного определения положения металлических деталей.</p>', '<p>LJ8A3-2-Z/BX NO NPN 6-36VDC Датчик индуктивный M8 дистанция 2 мм трехпроводной — высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения присутствия и положения металлических объектов. Этот датчик выполнен в цилиндрическом металлическом корпусе M8 с резьбовым креплением для удобной установки. Он работает в диапазоне напряжения 6-36В постоянного тока и имеет трехпроводное подключение (тип NPN NO). Благодаря индуктивному принципу, он обеспечивает высокую надежность, долговечность и стабильность работы, что упрощает его интеграцию в системы автоматизации. Датчик широко применяется на автоматизированных линиях, конвейерах и в различных механизмах для точного определения положения металлических деталей.</p>', 'LJ8A3-2-Z/BX NO NPN 6-36VDC M8 induktiv datchigi, 2 mm masofali, uch simli – metall obyektlarning mavjudligi va joylashuvini kontaktsiz aniqlash uchun mo‘ljallangan yuqori aniqlikdagi qurilma. Ushbu datchik oson o‘rnatish uchun M8 silindrsimon metall korpusda rezbali mahkamlagich bilan tayyorlangan. U 6-36V o‘zgarmas tok kuchlanishida ishlaydi va uch simli ulanishga ega (NPN NO turi). Induktiv tamoyil tufayli u yuqori ishonchlilik, uzoq muddat xizmat qilish va barqaror ishlashni ta’minlaydi, bu esa uni avtomatlashtirish tizimlariga oson integratsiya qilish imkonini beradi. Datchik avtomatlashtirilgan liniyalarda, konveyerlarda va turli mexanizmlarda metall detallarning aniq joylashuvini aniqlash uchun keng qo‘llaniladi.', 'induktivnyy-datchik-m12', 'induktivnyy-datchik-m12', 'induktiv-sensor-m12', '2600100000757', '08517002017000000', '1350310', false, 50300.00, 0.00, 249, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '07bcf492-09bf-4cef-b51a-dc4ada6ab677', true, true, NULL);
INSERT INTO public.products VALUES ('491d209e-88ad-4c78-a594-30bc06176e0b', '2025-12-03 06:13:18.832319+00', '2025-12-06 08:35:32.377704+00', '5ab28057-4307-11ee-a81c-ea27087631a9', '4086', 'HDR-100-24 MEAN WELL - блок питания, 24В, 3.96A, для монтажа на DIN-рейку', 'HDR-100-24 MEAN WELL - блок питания, 24В, 3.96A, для монтажа на DIN-рейку', 'Schneider Electric EasyPact EZC100H 100A', '<p>Автоматический выключатель в литом корпусе (MCCB) HDR-100-24 MEAN WELL - блок питания, 24В, 3.96A, для монтажа на DIN-рейку предназначен для надежной защиты электрических систем от перегрузок и коротких замыканий. Этот трехполюсный автоматический выключатель с номинальным током 100 Ампер обеспечивает отключающую способность до 30 кА при напряжении 380/400/415В, гарантируя безопасность электрооборудования и сети. Его прочная конструкция, простота монтажа и соответствие стандартам IEC 60947-2 делают его идеальным выбором для использования в промышленных панелях, коммерческих зданиях и распределительных щитах. HDR-100-24 MEAN WELL - блок питания, 24В, 3.96A, для монтажа на DIN-рейку обеспечивает высокую надежность и долгий срок службы, повышая стабильность электроснабжения. Данное устройство гарантирует безопасную и стабильную работу в электрических распределительных системах.</p>', '<p>Автоматический выключатель в литом корпусе (MCCB) HDR-100-24 MEAN WELL - блок питания, 24В, 3.96A, для монтажа на DIN-рейку предназначен для надежной защиты электрических систем от перегрузок и коротких замыканий. Этот трехполюсный автоматический выключатель с номинальным током 100 Ампер обеспечивает отключающую способность до 30 кА при напряжении 380/400/415В, гарантируя безопасность электрооборудования и сети. Его прочная конструкция, простота монтажа и соответствие стандартам IEC 60947-2 делают его идеальным выбором для использования в промышленных панелях, коммерческих зданиях и распределительных щитах. HDR-100-24 MEAN WELL - блок питания, 24В, 3.96A, для монтажа на DIN-рейку обеспечивает высокую надежность и долгий срок службы, повышая стабильность электроснабжения. Данное устройство гарантирует безопасную и стабильную работу в электрических распределительных системах.</p>', 'Schneider Electric EasyPact EZC100H 100A quyma korpusli avtomatik o‘chirgich (MCCB) elektr tizimlarini haddan tashqari yuklanish va qisqa tutashuvlardan ishonchli himoya qilishga mo‘ljallangan. Nominal toki 100 amper bo‘lgan uch qutbli avtomatik o‘chirgich 380/400/415V kuchlanishda 30 kA gacha uzish qobiliyatini ta’minlaydi, bu esa elektr uskunalari va tarmoq xavfsizligini kafolatlaydi. Uning pishiq konstruksiyasi, o‘rnatishning osonligi va IEC 60947-2 standartlariga muvofiqligi uni sanoat panellari, tijorat binolari va taqsimlash shitlarida qo‘llash uchun eng maqbul tanlovga aylantiradi. EasyPact EZC100H yuqori ishonchlilik va uzoq xizmat muddatini ta’minlab, elektr ta’minoti barqarorligini oshiradi. Ushbu qurilma elektr taqsimlash tizimlarida xavfsiz va barqaror ishlashni kafolatlaydi.', 'schneider-electric-easypact-ezc100h-avtomaticheskiy-vyklyuchatel', 'schneider-electric-easypact-ezc100h-avtomaticheskiy-vyklyuchatel', 'schneider-electric-easypact-ezc100h-avtomatik-ochirgich', '2600100006827', '08504003009000007', '1726381', false, 227000.00, 0.00, 33, 'draft', false, NULL, NULL, 'd24b0d79-31c5-4e05-b97b-24ca82f46ad1', true, true, NULL);
