INSERT INTO public.products VALUES ('0371e4c7-d07b-42e5-9dbe-d179b2a83a31', '2025-11-06 13:09:30.997209+00', '2025-12-04 09:28:36.515987+00', '453dc5a0-7358-11ef-a13c-005056b88cb9', '5083', 'Трех позиционный переключатель YCBZ-125 4P 100A', 'Трех позиционный переключатель YCBZ-125 4P 100A', 'CNC YCBZ 4-qutbli yuklama o''chirgichi 400V AC-22A', '<p>4-полюсный выключатель нагрузки серии CNC YCBZ предназначен для ручного подключения, отключения и безопасной изоляции электрических цепей низкого напряжения от источника питания. Соответствуя стандарту IEC/EN 60947-3 и категории применения AC-22A, данное устройство обеспечивает надежное переключение смешанных резистивных и индуктивных нагрузок. Прочный корпус и заметная красная рукоятка управления гарантируют долговечность и стабильную работу. Благодаря простоте монтажа и четкой индикации ON/OFF, он идеально подходит для использования в распределительных щитах, промышленных панелях управления, системах автоматизации и других областях, где требуется надежное ручное коммутационное оборудование.</p>', '<p>4-полюсный выключатель нагрузки серии CNC YCBZ предназначен для ручного подключения, отключения и безопасной изоляции электрических цепей низкого напряжения от источника питания. Соответствуя стандарту IEC/EN 60947-3 и категории применения AC-22A, данное устройство обеспечивает надежное переключение смешанных резистивных и индуктивных нагрузок. Прочный корпус и заметная красная рукоятка управления гарантируют долговечность и стабильную работу. Благодаря простоте монтажа и четкой индикации ON/OFF, он идеально подходит для использования в распределительных щитах, промышленных панелях управления, системах автоматизации и других областях, где требуется надежное ручное коммутационное оборудование.</p>', 'CNC YCBZ seriyali 4-qutbli yuklama o''chirgichi past kuchlanishli elektr zanjirlarini qo''lda ulash va uzish, shuningdek, uskunalarni quvvat manbaidan xavfsiz ajratish uchun mo''ljallangan. Ushbu qurilma IEC/EN 60947-3 standarti bo''yicha AC-22A foydalanish toifasiga mos keladi, bu aralash rezistiv va induktiv yuklarni o''z ichiga olgan yuklarni kommutatsiyalash imkonini beradi. Uning mustahkam korpusi va qizil rangli boshqaruv tutqichi uzoq muddatli va ishonchli ishlashni ta''minlaydi. Oson o''rnatish va aniq ON/OFF ko''rsatkichi uni tarqatish panellari, sanoat uskunalarini boshqarish va boshqa avtomatlashtirish tizimlarida xavfsiz elektr izolyatsiyasini ta''minlash uchun ideal tanlovga aylantiradi.', NULL, NULL, 'cnc-ycbz-4-qutbli-yuklama-ochirgichi-400v-ac-22a', '2600100030198', '08536001037000001', '1377174', false, 397500.00, 0.00, 0, 'published', false, NULL, NULL, '3cac6bec-9e7b-4d07-ae48-0669adb4a9c7', true, true, NULL);
