INSERT INTO public.products VALUES ('f6dbbe76-dce9-45de-861d-87ff446e835e', '2025-12-06 10:36:55.713134+00', '2026-03-01 07:40:15.255474+00', '01ef1225-9dee-11f0-a14e-005056b88cb9', '6477', 'LJ38A4-25-Z/CY NO+NC PNP 6-36VDC Датчик индуктивный M38 дистанция 25 мм четырехпроводной', 'LJ38A4-25-Z/CY NO+NC PNP 6-36VDC Датчик индуктивный M38 дистанция 25 мм четырехпроводной', '', NULL, NULL, NULL, 'lj38a4-25-zcy-nonc-pnp-6-36vdc-datchik-induktivnyy-m38-distantsiya-25-mm-chetyrekhprovodnoy', 'lj38a4-25-zcy-nonc-pnp-6-36vdc-datchik-induktivnyy-m38-distantsiya-25-mm-chetyrekhprovodnoy', 'lj38a4-25-z-cy-no-nc-pnp-6-36vdc-datchik-induktivnyy-m38-distantsiya-25-mm-chetyrekhprovodnoy', '2600100030624', '08517002017000000', '1350310', false, 125000.00, 0.00, 10, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '22e7d30c-2557-42c0-97e3-f102e2e34cc3', true, false, NULL);
INSERT INTO public.products VALUES ('6b916da0-c881-49a3-be84-d8249f1efa4f', '2026-02-14 10:16:36.605632+00', '2026-03-01 07:40:15.429255+00', '3b0b5d5d-c458-11f0-a150-005056b88cb9', '6589', 'HO-12P3 / HX-DGS-12P3 PNP NO+NC, кольцевой индуктивный датчик, внутренний диаметр 12 мм, питание 10–', 'HO-12P3 / HX-DGS-12P3 PNP NO+NC, кольцевой индуктивный датчик, внутренний диаметр 12 мм, питание 10–', 'HO-12P3 / HX-DGS-12P3 PNP NO+NC, halqasimon induktiv sensor, ichki diametri 12 millimetr bo‘lgan, 10- volt kuchlanish bilan ta’minlanadigan', '<p>HO-12P3 / HX-DGS-12P3 PNP NO+NC, кольцевой индуктивный датчик, внутренний диаметр 12 мм, питание 10– — это высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов, проходящих через его кольцевое отверстие. Этот кольцевой датчик идеально подходит для автоматизации конвейерных линий, систем подсчета объектов и контроля положения изделий небольшого размера. Его внутренний диаметр 12 мм обеспечивает точное срабатывание для мелких деталей. Выходная конфигурация PNP NO+NC гарантирует надежное переключение сигнала в зависимости от наличия или отсутствия объекта, а прочный корпус обеспечивает стабильную и долговечную работу в сложных промышленных условиях. Простота установки и легкая интеграция в существующие системы автоматизации делают его незаменимым компонентом для повышения эффективности производства.</p>', '<p>HO-12P3 / HX-DGS-12P3 PNP NO+NC, кольцевой индуктивный датчик, внутренний диаметр 12 мм, питание 10– — это высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов, проходящих через его кольцевое отверстие. Этот кольцевой датчик идеально подходит для автоматизации конвейерных линий, систем подсчета объектов и контроля положения изделий небольшого размера. Его внутренний диаметр 12 мм обеспечивает точное срабатывание для мелких деталей. Выходная конфигурация PNP NO+NC гарантирует надежное переключение сигнала в зависимости от наличия или отсутствия объекта, а прочный корпус обеспечивает стабильную и долговечную работу в сложных промышленных условиях. Простота установки и легкая интеграция в существующие системы автоматизации делают его незаменимым компонентом для повышения эффективности производства.</p>', 'HO-12P3 / HX-DGS-12P3 PNP NO+NC - ichki diametri 12 mm bo‘lgan halqali induktiv datchik bo‘lib, 10-30 V kuchlanish bilan ishlaydi. Bu yuqori aniqlikdagi datchik o‘zining halqasimon teshigidan o‘tayotgan metall jismlarni kontaktsiz aniqlash uchun mo‘ljallangan. Ushbu halqali datchik konveyer liniyalarini avtomatlashtirish, obyektlarni hisoblash tizimlari va kichik o‘lchamli mahsulotlar holatini nazorat qilish uchun juda qulay. 12 mm ichki diametri tufayli mayda detallarni aniq aniqlaydi. PNP NO+NC chiqish konfiguratsiyasi obyektning bor-yo‘qligiga qarab signalni ishonchli o‘zgartirishni ta’minlaydi. Mustahkam korpusi esa murakkab sanoat sharoitlarida barqaror va uzoq muddat ishlashiga imkon beradi. O‘rnatish osonligi va mavjud avtomatlashtirish tizimlariga osongina qo‘shilishi uni ishlab chiqarish samaradorligini oshirishning ajralmas qismiga aylantiradi.', 'ho-12p3-hx-dgs-12p3-pnp-no-nc-koltsevoy-induktivnyy-datchik-vnutrenniy-diametr-12-mm-pitaniye-10', 'ho-12p3-hx-dgs-12p3-pnp-no-nc-koltsevoy-induktivnyy-datchik-vnutrenniy-diametr-12-mm-pitaniye-10', 'ho-12p3-hx-dgs-12p3-pnp-no-nc-koltsevoy-induktivnyy-datchik-vnutrenniy-diametr-12-mm-pitaniye-10', '2600100031744', '08517002017000000', '1350310', false, 115000.00, 0.00, 5, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '2dcfe231-bb9d-4b84-86b4-b92100aebbb6', true, true, NULL);
