INSERT INTO public.products VALUES ('1d375593-3f84-4e0d-a6fd-a198a1a3a0a4', '2025-12-12 10:58:56.214185+00', '2026-03-01 07:40:17.012055+00', '6b19123d-8d80-11ed-a805-bb22e695b629', '3459', 'LJ30A3-10-Z/BX NO NPN 6-36VDC Датчик индуктивный M30 дистанция 10 мм трехпроводной', 'LJ30A3-10-Z/BX NO NPN 6-36VDC Датчик индуктивный M30 дистанция 10 мм трехпроводной', NULL, NULL, NULL, NULL, 'lj30a3-10-zbx-no-npn-6-36vdc-datchik-induktivnyy-m30-distantsiya-10-mm-trekhprovodnoy', 'lj30a3-10-zbx-no-npn-6-36vdc-datchik-induktivnyy-m30-distantsiya-10-mm-trekhprovodnoy', NULL, '2600100000993', '08517002017000000', '1350310', false, 126300.00, 0.00, 38, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, 'f8421bbe-ea3f-420b-a9f0-aa296263aff1', true, false, NULL);
INSERT INTO public.products VALUES ('b7680ba3-316d-4e5e-947d-7578f013fdc3', '2025-12-12 12:00:58.130521+00', '2026-03-01 07:40:14.609276+00', 'e0caad7d-b370-11ee-a12b-005056b88cb9', '4348', 'PR18-8DP NO PNP 10–30VDC Датчик индуктивный M18 дистанция 8 мм трехпроводной', 'PR18-8DP NO PNP 10–30VDC Датчик индуктивный M18 дистанция 8 мм трехпроводной', 'PR18-8DP NO PNP 10-30VDC induktiv sensor, M18 o‘lchamli, 8 mm masofali, uch simli', '<p>PR18-8DP NO PNP 10–30VDC Датчик индуктивный M18 дистанция 8 мм трехпроводной — это надежный промышленный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Этот индуктивный датчик имеет цилиндрический резьбовой корпус M18, легко монтируется и подключается через трехпроводной кабель. Он работает от источника питания 10-30 В постоянного тока и способен точно определять объекты на расстоянии до 8 мм, обеспечивая стабильную работу в системах автоматизации. Благодаря типу выхода PNP и высокой точности, датчик идеально подходит для использования на автоматизированных производственных линиях, конвейерах и в различном промышленном оборудовании. Его прочная конструкция и простота внедрения гарантируют длительный срок службы и беспроблемную интеграцию в системы.</p>', '<p>PR18-8DP NO PNP 10–30VDC Датчик индуктивный M18 дистанция 8 мм трехпроводной — это надежный промышленный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Этот индуктивный датчик имеет цилиндрический резьбовой корпус M18, легко монтируется и подключается через трехпроводной кабель. Он работает от источника питания 10-30 В постоянного тока и способен точно определять объекты на расстоянии до 8 мм, обеспечивая стабильную работу в системах автоматизации. Благодаря типу выхода PNP и высокой точности, датчик идеально подходит для использования на автоматизированных производственных линиях, конвейерах и в различном промышленном оборудовании. Его прочная конструкция и простота внедрения гарантируют длительный срок службы и беспроблемную интеграцию в системы.</p>', 'PR18-8DP NO PNP 10-30VDC M18 induktiv datchigi, 8 mm masofali, uch simli - bu metall obyektlarni kontaktsiz aniqlash uchun mo‘ljallangan ishonchli sanoat sensoridir. Bu induktiv datchik M18 silindrik rezbali korpusga ega bo‘lib, oson o‘rnatiladi va uch simli kabel orqali ulanadi. U 10-30 V o‘zgarmas tok manbaida ishlaydi va 8 mm gacha masofadagi obyektlarni aniq aniqlab, avtomatlashtirish tizimlarida barqaror ishlashni ta’minlaydi. PNP chiqish turi va yuqori aniqligi tufayli, bu datchik avtomatlashtirilgan ishlab chiqarish liniyalari, konveyerlar va turli xil sanoat uskunalarida qo‘llash uchun juda mos keladi. Uning mustahkam konstruktsiyasi va qo‘llashning soddaligi uzoq muddat xizmat qilishini va tizimlarga muammosiz integratsiyalashuvini kafolatlaydi.', 'pr18-8dp-no-pnp-10-30vdc-datchik-induktivnyy-m18-distantsiya-8-mm-trekhprovodnoy', 'pr18-8dp-no-pnp-10-30vdc-datchik-induktivnyy-m18-distantsiya-8-mm-trekhprovodnoy', 'pr18-8dp-no-pnp-10-30vdc-datchik-induktivnyy-m18-distantsiya-8-mm-trekhprovodnoy', '2600100001068', '08517002017000000', '1350310', false, 81100.00, 0.00, 66, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, 'a687b613-631f-4c34-9b97-cab3064eed92', true, true, NULL);
INSERT INTO public.products VALUES ('46b1d571-13ca-41f7-bd60-2dabfb291485', '2026-02-14 09:41:28.265281+00', '2026-03-01 07:40:14.845542+00', '0ccd62df-b374-11ee-a12b-005056b88cb9', '4374', 'GKB-M0524PA PNP NO 10–30VDC, индуктивный датчик прямоугольный, дистанция 5 мм', 'GKB-M0524PA PNP NO 10–30VDC, индуктивный датчик прямоугольный, дистанция 5 мм', 'GKB-M0524PA PNP NO 10-30VDC, to‘g‘ri burchakli induktiv sezgich, 5 mm masofali', '<p>GKB-M0524PA PNP NO 10–30VDC, индуктивный датчик прямоугольный, дистанция 5 мм — это высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Обладая выходом PNP NO и диапазоном напряжения 10-30VDC, он обеспечивает легкую интеграцию в существующие системы автоматизации. Данный датчик способен точно работать на расстоянии до 5 мм, имеет прочный прямоугольный пластиковый корпус с монтажными отверстиями и кабельное подключение, что упрощает установку. Благодаря высокой надежности, стабильности работы и долгому сроку службы, он широко применяется на производственных линиях, конвейерах и в машиностроении для контроля положения и наличия объектов.</p>', '<p>GKB-M0524PA PNP NO 10–30VDC, индуктивный датчик прямоугольный, дистанция 5 мм — это высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Обладая выходом PNP NO и диапазоном напряжения 10-30VDC, он обеспечивает легкую интеграцию в существующие системы автоматизации. Данный датчик способен точно работать на расстоянии до 5 мм, имеет прочный прямоугольный пластиковый корпус с монтажными отверстиями и кабельное подключение, что упрощает установку. Благодаря высокой надежности, стабильности работы и долгому сроку службы, он широко применяется на производственных линиях, конвейерах и в машиностроении для контроля положения и наличия объектов.</p>', 'GKB-M0524PA PNP NO 10-30VDC, to‘g‘ri burchakli induktiv datchik, masofasi 5 mm - bu metall obyektlarni kontaktsiz aniqlash uchun mo‘ljallangan yuqori aniqlikdagi induktiv datchikdir. U PNP NO chiqishi va 10-30VDC kuchlanish diapazoniga ega bo‘lib, mavjud avtomatlashtirish tizimlariga oson integratsiyalashuvni ta’minlaydi. Ushbu datchik 5 mm masofagacha aniq ishlash qobiliyatiga ega, o‘rnatish teshiklari va kabel ulanishiga ega bo‘lgan mustahkam to‘g‘ri burchakli plastik korpusga ega, bu esa o‘rnatishni osonlashtiradi. Yuqori ishonchliligi, barqaror ishlashi va uzoq muddat xizmat ko‘rsatishi tufayli u ishlab chiqarish liniyalarida, konveyerlarda va mashinasozlikda obyektlarning holatini va mavjudligini nazorat qilish uchun keng qo‘llaniladi.', 'gkb-m0524pa-pnp-no-10-30vdc-induktivnyy-datchik-pryamougolnyy-distantsiya-5-mm', 'gkb-m0524pa-pnp-no-10-30vdc-induktivnyy-datchik-pryamougolnyy-distantsiya-5-mm', 'gkb-m0524pa-pnp-no-10-30vdc-induktivnyy-datchik-pryamougolnyy-distantsiya-5-mm', '2600100002188', '08517002017000000', '1350310', false, 128600.00, 0.00, 31, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '2354690e-f7eb-47d3-9103-6ca8bea347f0', true, true, NULL);
