INSERT INTO public.products VALUES ('9166cd87-6183-4a05-9c7e-01743e5d076a', '2026-02-14 10:16:39.420666+00', '2026-03-01 07:40:15.462807+00', '42981330-c458-11f0-a150-005056b88cb9', '6590', 'HO-30N3 / HX-DGS-30N3 NPN NO+NC, кольцевой индуктивный датчик, внутренний диаметр 30 мм, питание 10–', 'HO-30N3 / HX-DGS-30N3 NPN NO+NC, кольцевой индуктивный датчик, внутренний диаметр 30 мм, питание 10–', 'HO-30N3 / HX-DGS-30N3 NPN NO+NC, ichki diametri 30 mm bo‘lgan halqasimon induktiv sensor, ta’minot kuchlanishi 10-', '<p>HO-30N3 / HX-DGS-30N3 NPN NO+NC, кольцевой индуктивный датчик, внутренний диаметр 30 мм, питание 10– — это высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Оснащенный выходной конфигурацией NPN NO+NC и внутренним диаметром 30 мм, он идеально подходит для детектирования мелких металлических деталей или инструментов на автоматизированных производственных линиях и конвейерах. Его надежность и стабильность работы обеспечивают легкую интеграцию в любые системы автоматизации. Датчик повышает эффективность производственных процессов за счет быстрого и точного обнаружения металлических объектов. Изготовленный из высококачественных материалов, он гарантирует долгий срок службы и устойчивость к сложным промышленным условиям.</p>', '<p>HO-30N3 / HX-DGS-30N3 NPN NO+NC, кольцевой индуктивный датчик, внутренний диаметр 30 мм, питание 10– — это высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Оснащенный выходной конфигурацией NPN NO+NC и внутренним диаметром 30 мм, он идеально подходит для детектирования мелких металлических деталей или инструментов на автоматизированных производственных линиях и конвейерах. Его надежность и стабильность работы обеспечивают легкую интеграцию в любые системы автоматизации. Датчик повышает эффективность производственных процессов за счет быстрого и точного обнаружения металлических объектов. Изготовленный из высококачественных материалов, он гарантирует долгий срок службы и устойчивость к сложным промышленным условиям.</p>', 'HO-30N3 / HX-DGS-30N3 NPN NO+NC - bu 30 mm ichki diametrli halqasimon induktiv datchik bo‘lib, 10–30 V kuchlanish bilan ta’minlanadi. U metall obyektlarni kontaktsiz aniqlash uchun mo‘ljallangan yuqori aniqlikdagi qurilmadir. NPN NO+NC chiqish konfiguratsiyasi va 30 mm ichki diametri bilan jihozlangan bu datchik, avtomatlashtirilgan ishlab chiqarish liniyalari va konveyerlarda kichik metall qismlar yoki asboblarni aniqlash uchun juda qulay. Uning ishonchliligi va barqaror ishlashi har qanday avtomatlashtirish tizimlariga oson integratsiyalashuvini ta’minlaydi. Datchik metall buyumlarni tez va aniq aniqlash orqali ishlab chiqarish jarayonlarining samaradorligini oshiradi. Yuqori sifatli materiallardan tayyorlangan bu qurilma uzoq muddat xizmat qilishi va murakkab sanoat sharoitlariga chidamliligini kafolatlaydi.', 'ho-30n3-hx-dgs-30n3-npn-no-nc', 'ho-30n3-hx-dgs-30n3-npn-no-nc', 'ho-30n3-hx-dgs-30n3-npn-no-nc', '2600100031751', '08517002017000000', '1350310', false, 115000.00, 0.00, 5, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '2dcfe231-bb9d-4b84-86b4-b92100aebbb6', true, true, NULL);
INSERT INTO public.products VALUES ('9c8e77c8-fd9a-42d5-8262-07884c7885c2', '2025-12-03 06:13:18.482293+00', '2026-03-01 07:40:16.585011+00', 'a37b1b28-3a3c-11ed-a7fd-f56a4477b039', '3131', 'HDR-15-12 MEAN WELL - блок питания, 12В, 1.25A, для монтажа на DIN-рейку', 'HDR-15-12 MEAN WELL - блок питания, 12В, 1.25A, для монтажа на DIN-рейку', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2600100006759', '08504003009000007', '1726381', false, 112400.00, 0.00, 52, 'pending', false, NULL, NULL, NULL, true, false, NULL);
INSERT INTO public.products VALUES ('3a704b89-ab09-412a-a976-7c828ba4ef94', '2025-11-06 13:09:30.9818+00', '2026-03-01 07:40:14.880649+00', 'eaa006f4-b4fc-11ee-a12b-005056b88cb9', '4426', 'Авт. выкл. Easypact EZC100H - TMD - 100 A - 3 полюса 3Т', 'Авт. выкл. Easypact EZC100H - TMD - 100 A - 3 полюса 3Т', 'Schneider Electric EasyPact EZC100H 3P 100A', '<p>Автоматический выключатель в литом корпусе Schneider Electric EasyPact EZC100H 3P 100A представляет собой надежное трехполюсное устройство, предназначенное для эффективной защиты электрических цепей и оборудования от перегрузок и коротких замыканий. Обладая номинальным током 100А и изоляционным напряжением 690В, этот компактный выключатель серии EasyPact EZC100H обеспечивает высокий уровень безопасности и стабильность работы вашей электроустановки. Соответствуя стандарту IEC 60947-2, он гарантирует превосходную предельную отключающую способность до 30кА при 400В, что делает его идеальным для использования в распределительных щитах, промышленных панелях и системах защиты ответвлений. Прочная конструкция и удобные терминалы обеспечивают простоту монтажа и долговечность эксплуатации, подтверждая надежность устройства.</p>', '<p>Автоматический выключатель в литом корпусе Schneider Electric EasyPact EZC100H 3P 100A представляет собой надежное трехполюсное устройство, предназначенное для эффективной защиты электрических цепей и оборудования от перегрузок и коротких замыканий. Обладая номинальным током 100А и изоляционным напряжением 690В, этот компактный выключатель серии EasyPact EZC100H обеспечивает высокий уровень безопасности и стабильность работы вашей электроустановки. Соответствуя стандарту IEC 60947-2, он гарантирует превосходную предельную отключающую способность до 30кА при 400В, что делает его идеальным для использования в распределительных щитах, промышленных панелях и системах защиты ответвлений. Прочная конструкция и удобные терминалы обеспечивают простоту монтажа и долговечность эксплуатации, подтверждая надежность устройства.</p>', 'Schneider Electric EasyPact EZC100H 3P 100A – bu turli elektr tizimlarida ortiqcha yuklanish va qisqa tutashuvdan ishonchli himoya qilish uchun mo''ljallangan mustahkam 3 qutbli kalitli avtomatik o''chirgich (MCCB). Nominal toki 100A va izolyatsiya kuchlanishi 690V bo''lgan ushbu ixcham qurilma elektr zanjirlaringiz va uskunangiz uchun yuqori darajadagi xavfsizlik va barqaror ishlashni ta''minlaydi. IEC 60947-2 standartlariga mos keladigan ushbu avtomatik o''chirgich 400V kuchlanishda 30kA gacha bo''lgan yuqori yakuniy qisqa tutashuvni uzish qobiliyatiga ega bo''lib, sanoat panellari, tijorat binolarining taqsimlash shitlari va tarmoq zanjirlarini himoyalashda ishonchli ishlashni kafolatlaydi. Uning mustahkam konstruksiyasi va qulay terminallari montajni osonlashtirib, uzoq muddatli ishonchlilik va xavfsiz elektr taqsimotini ta''minlaydi.', NULL, NULL, 'schneider-electric-easypact-ezc100h-3p-100a', '3303430301295', '08536001037000001', '1377174', false, 1025000.00, 0.00, -5, 'pending', false, '3dd065bb-897d-4e64-b0de-f98b7e432ced', NULL, '0592e97f-7d22-407a-a2ef-015ba3bb925c', true, true, NULL);
