INSERT INTO public.products VALUES ('451338d5-3768-4665-a99b-bc2da3e215b3', '2025-11-13 09:55:50.807121+00', '2026-03-01 07:40:15.688963+00', '46e80023-e793-11ea-a7a5-e117a061f846', '183', 'NXB-63 1P 63A CHINT - автоматический выключатель, 6кА, характеристика C', 'NXB-63 1P 63A CHINT - автоматический выключатель, 6кА, характеристика C', 'CHNT NXB-63 C40 avtomatik o''chirgich, 40A', '<p>Автоматический выключатель CHNT NXB-63 C40 предназначен для эффективной защиты электрических цепей от перегрузок и коротких замыканий. Этот однополюсный модуль с номинальным током 40А рассчитан на напряжение 230В и частоту 50Гц, обеспечивая отключающую способность до 10 кА. Соответствие стандартам IEC60898-1 и GB10963.1 гарантирует надежность и безопасность в эксплуатации, а удобное крепление на DIN-рейку упрощает монтаж.</p>', '<p>Автоматический выключатель CHNT NXB-63 C40 предназначен для эффективной защиты электрических цепей от перегрузок и коротких замыканий. Этот однополюсный модуль с номинальным током 40А рассчитан на напряжение 230В и частоту 50Гц, обеспечивая отключающую способность до 10 кА. Соответствие стандартам IEC60898-1 и GB10963.1 гарантирует надежность и безопасность в эксплуатации, а удобное крепление на DIN-рейку упрощает монтаж.</p>', 'Ushbu CHNT NXB-63 C40 avtomatik o''chirgich elektr tarmoqlarini qisqa tutashuv va ortiqcha yuklanishdan himoya qilish uchun mo''ljallangan. 230V kuchlanish va 50Hz chastotali tizimlar uchun 40A nominal tokga ega bo''lib, 10kA gacha bo''lgan uzilish quvvatini ta''minlaydi. Uning DIN reykasiga oson o''rnatilishi va IEC60898-1 hamda GB10963.1 standartlariga muvofiqligi elektr tizimlarida yuqori ishonchlilik va xavfsizlikni kafolatlaydi.', NULL, NULL, '11111', '6901800721819', '08536001037000001', '1377174', false, 15000.00, 0.00, 63, 'pending', false, NULL, NULL, 'd1d518ea-d45f-4476-a0a7-f350b1d0b4e3', true, true, NULL);
