INSERT INTO public.products VALUES ('1c38033a-f924-4b82-8a99-301de3aff506', '2025-12-12 10:58:54.169201+00', '2026-03-01 07:40:14.362508+00', '6df89cb7-b36f-11ee-a12b-005056b88cb9', '4340', 'LJ30A3-15-Z/EX NO 6-36VDC Датчик индуктивный M30 дистанция 15 мм двухпроводной', 'LJ30A3-15-Z/EX NO 6-36VDC Датчик индуктивный M30 дистанция 15 мм двухпроводной', NULL, NULL, NULL, NULL, 'lj30a3-15-zex-no-6-36vdc-datchik-induktivnyy-m30-distantsiya-15-mm-dvukhprovodnoy', 'lj30a3-15-zex-no-6-36vdc-datchik-induktivnyy-m30-distantsiya-15-mm-dvukhprovodnoy', NULL, '2600100000955', '08517002017000000', '1350310', false, 107100.00, 0.00, 8, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, 'f8421bbe-ea3f-420b-a9f0-aa296263aff1', true, false, NULL);
INSERT INTO public.products VALUES ('452fffdd-4f9d-4148-b41b-71363792be9a', '2025-12-12 12:01:00.050249+00', '2026-03-01 07:40:15.313118+00', '116e6877-c458-11f0-a150-005056b88cb9', '6586', 'PR12-4DP2 PNP NC 10–30VDC, датчик индуктивный M12, дистанция 4 мм, трёхпроводной', 'PR12-4DP2 PNP NC 10–30VDC, датчик индуктивный M12, дистанция 4 мм, трёхпроводной', 'PR12-4DP2 PNP NC 10-30VDC, M12 induktiv sezgich, 4 mm masofali, uch simli', '<p>PR12-4DP2 PNP NC 10–30VDC, датчик индуктивный M12, дистанция 4 мм, трёхпроводной — это высокоточный индуктивный датчик, разработанный для бесконтактного обнаружения наличия, положения или присутствия металлических объектов в промышленных системах автоматизации. Он выполнен в металлическом цилиндрическом корпусе размера M12 с резьбовым креплением, что обеспечивает удобство монтажа. Данный трёхпроводной датчик функционирует в диапазоне напряжений от 10 до 30 В постоянного тока и имеет выходную конфигурацию PNP NC (нормально замкнутый), обеспечивая дистанцию срабатывания до 4 мм. Его надёжность, долговечность и стабильность работы делают его идеальным решением для автоматизированных производственных линий, конвейерных систем и другого оборудования.</p>', '<p>PR12-4DP2 PNP NC 10–30VDC, датчик индуктивный M12, дистанция 4 мм, трёхпроводной — это высокоточный индуктивный датчик, разработанный для бесконтактного обнаружения наличия, положения или присутствия металлических объектов в промышленных системах автоматизации. Он выполнен в металлическом цилиндрическом корпусе размера M12 с резьбовым креплением, что обеспечивает удобство монтажа. Данный трёхпроводной датчик функционирует в диапазоне напряжений от 10 до 30 В постоянного тока и имеет выходную конфигурацию PNP NC (нормально замкнутый), обеспечивая дистанцию срабатывания до 4 мм. Его надёжность, долговечность и стабильность работы делают его идеальным решением для автоматизированных производственных линий, конвейерных систем и другого оборудования.</p>', 'PR12-4DP2 PNP NC 10-30VDC, M12 o‘lchamli induktiv datchik, 4 mm masofali, uch simli - bu sanoat avtomatlashtirish tizimlarida metall obyektlarning mavjudligi, joylashuvi yoki borligini kontaktsiz aniqlash uchun ishlab chiqarilgan yuqori aniqlikdagi induktiv datchikdir. U M12 o‘lchamli metall silindrik korpusda rezbali mahkamlash bilan tayyorlangan bo‘lib, bu o‘rnatishni osonlashtiradi. Ushbu uch simli datchik 10 dan 30 V gacha bo‘lgan o‘zgarmas tok kuchlanishida ishlaydi va 4 mm gacha bo‘lgan masofada ishlaydigan PNP NC (normal yopiq) chiqish konfiguratsiyasiga ega. Uning ishonchliligi, chidamliligi va barqaror ishlashi uni avtomatlashtirilgan ishlab chiqarish liniyalari, konveyer tizimlari va boshqa uskunalar uchun ideal yechimga aylantiradi.', 'pr12-4dp2-pnp-nc-10-30vdc-datchik-induktivnyy-m12-distantsiya-4-mm-trekhprovodnoy', 'pr12-4dp2-pnp-nc-10-30vdc-datchik-induktivnyy-m12-distantsiya-4-mm-trekhprovodnoy', 'pr12-4dp2-pnp-nc-10-30vdc-datchik-induktivnyy-m12-distantsiya-4-mm-trekhprovodnoy', '2600100031713', '08517002017000000', '1350310', false, 66500.00, 0.00, 10, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '623416ef-7b86-4113-8335-377602521d45', true, true, NULL);
