INSERT INTO public.products VALUES ('c3a04a9f-b874-4b05-a626-4304b84c3fb2', '2025-12-03 06:13:18.789384+00', '2026-03-01 07:40:17.515253+00', '7cfc20a6-08ed-11ee-a812-68ecc5c3e82a', '3873', 'DRT-480-24 MEAN WELL - блок питания, 24В, 20A, трёхфазный, для монтажа на DIN-рейку', 'DRT-480-24 MEAN WELL - блок питания, 24В, 20A, трёхфазный, для монтажа на DIN-рейку', 'DRT-480-24 MEAN WELL - DIN-reykaga o‘rnatiladigan, uch fazali, 24 volt, 20 amperli ta’minot bloki', '<p>DRT-480-24 MEAN WELL - блок питания, 24В, 20A, трёхфазный, для монтажа на DIN-рейку — это высокоэффективный источник питания, предназначенный для использования в промышленных автоматизированных системах. Данное устройство преобразует трёхфазное переменное напряжение в стабильное постоянное напряжение 24В с током до 20А. Установка на DIN-рейку обеспечивает лёгкий и быстрый монтаж в распределительных щитах и шкафах управления. Продукция MEAN WELL отличается высокой надёжностью, долговечностью и стабильностью работы, что критически важно для обеспечения бесперебойного функционирования оборудования. Этот блок питания идеально подходит для низковольтных систем управления, приводных механизмов и различных компонентов промышленной автоматики.</p>', '<p>DRT-480-24 MEAN WELL - блок питания, 24В, 20A, трёхфазный, для монтажа на DIN-рейку — это высокоэффективный источник питания, предназначенный для использования в промышленных автоматизированных системах. Данное устройство преобразует трёхфазное переменное напряжение в стабильное постоянное напряжение 24В с током до 20А. Установка на DIN-рейку обеспечивает лёгкий и быстрый монтаж в распределительных щитах и шкафах управления. Продукция MEAN WELL отличается высокой надёжностью, долговечностью и стабильностью работы, что критически важно для обеспечения бесперебойного функционирования оборудования. Этот блок питания идеально подходит для низковольтных систем управления, приводных механизмов и различных компонентов промышленной автоматики.</p>', 'DRT-480-24 MEAN WELL - 24V, 20A, uch fazali, DIN-reykaga o‘rnatiladigan ta’minot bloki - bu sanoat avtomatlashtirish tizimlarida qo‘llash uchun yaratilgan yuqori samarali elektr ta’minoti manbaidir. Ushbu qurilma uch fazali o‘zgaruvchan kuchlanishni 20A gacha tok bilan 24V barqaror o‘zgarmas kuchlanishga aylantiradi. DIN-reykaga o‘rnatish imkoniyati taqsimlash shitlari va boshqaruv shkaflariga oson va tez o‘rnatishni ta’minlaydi. MEAN WELL mahsulotlari yuqori ishonchlilik, uzoq muddat xizmat qilish va barqaror ishlash xususiyatlari bilan ajralib turadi. Bu esa uskunaning uzluksiz ishlashini ta’minlash uchun juda muhimdir. Ushbu ta’minot bloki past kuchlanishli boshqaruv tizimlari, harakatlanish mexanizmlari va sanoat avtomatikasining turli komponentlari uchun aynan mosdir.', NULL, NULL, 'drt-480-24-mean-well-din-reykaga-ornatiladigan-uch-fazali-24-volt-20-amperli-taminot-bloki', '2600100006919', '08504003009000007', '1726381', false, 1969900.00, 0.00, 5, 'pending', false, NULL, NULL, NULL, true, false, NULL);
