INSERT INTO public.products VALUES ('45598215-bab3-417f-8c71-9d0afb086dda', '2025-12-03 06:13:18.12627+00', '2026-03-01 07:40:14.959507+00', '554d88fc-7101-11ef-a13c-005056b88cb9', '5079', 'TDR-960-24 MEAN WELL - блок питания, 24В, 40A, трёхфазный, для монтажа на DIN-рейку', 'TDR-960-24 MEAN WELL - блок питания, 24В, 40A, трёхфазный, для монтажа на DIN-рейку', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2600100022353', '08504003009000007', '1726381', false, 2882600.00, 0.00, 13, 'pending', false, NULL, NULL, NULL, true, false, NULL);
INSERT INTO public.products VALUES ('5ba202b4-d8b6-4d3a-a18e-5a5d47b77ca9', '2025-12-12 12:00:59.291101+00', '2026-03-01 07:40:14.728271+00', 'f922e30b-b370-11ee-a12b-005056b88cb9', '4351', 'PR30-10DP NO PNP 10–30VDC Датчик индуктивный M30 дистанция 10 мм трехпроводной', 'PR30-10DP NO PNP 10–30VDC Датчик индуктивный M30 дистанция 10 мм трехпроводной', 'PR30-10DP NO PNP 10-30VDC M30 induktiv sensorli, 10 mm masofali, uch simli datchik', '<p>PR30-10DP NO PNP 10–30VDC Датчик индуктивный M30 дистанция 10 мм трехпроводной — это высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Он широко применяется в системах промышленной автоматизации для контроля положения и присутствия объектов. Данный датчик оснащен резьбовым металлическим корпусом M30, имеет дистанцию срабатывания 10 мм и работает от напряжения 10-30VDC. Трехпроводное подключение с выходом типа PNP NO обеспечивает стабильную и надежную передачу сигнала, что гарантирует легкую интеграцию в производственные линии и конвейерные системы. Благодаря высокой надежности, долговечности и стабильности работы, этот датчик идеально подходит для эксплуатации в различных промышленных условиях.</p>', '<p>PR30-10DP NO PNP 10–30VDC Датчик индуктивный M30 дистанция 10 мм трехпроводной — это высокоточный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Он широко применяется в системах промышленной автоматизации для контроля положения и присутствия объектов. Данный датчик оснащен резьбовым металлическим корпусом M30, имеет дистанцию срабатывания 10 мм и работает от напряжения 10-30VDC. Трехпроводное подключение с выходом типа PNP NO обеспечивает стабильную и надежную передачу сигнала, что гарантирует легкую интеграцию в производственные линии и конвейерные системы. Благодаря высокой надежности, долговечности и стабильности работы, этот датчик идеально подходит для эксплуатации в различных промышленных условиях.</p>', 'PR30-10DP NO PNP 10-30VDC M30 induktiv datchigi, 10 mm masofali, uch simli - bu metall obyektlarni kontaktsiz aniqlash uchun mo‘ljallangan yuqori aniqlikdagi qurilmadir. U sanoat avtomatlashtirish tizimlarida obyektlarning joylashuvi va mavjudligini nazorat qilishda keng qo‘llaniladi. Ushbu datchik M30 rezbali metall korpusga ega bo‘lib, 10 mm masofada ishga tushadi va 10-30VDC kuchlanishda ishlaydi. PNP NO turidagi chiqishga ega uch simli ulanish tizimi signalni barqaror va ishonchli tarzda uzatishni ta’minlaydi, bu esa uni ishlab chiqarish liniyalari va konveyer tizimlariga oson integratsiyalash imkonini beradi. Yuqori ishonchliligi, uzoq muddatli xizmat qilishi va barqaror ishlashi tufayli bu datchik turli xil sanoat sharoitlarida foydalanish uchun juda qulay hisoblanadi.', 'pr30-10dp-no-pnp-10-30vdc-datchik-induktivnyy-m30-distantsiya-10-mm-trekhprovodnoy', 'pr30-10dp-no-pnp-10-30vdc-datchik-induktivnyy-m30-distantsiya-10-mm-trekhprovodnoy', 'pr30-10dp-no-pnp-10-30vdc-datchik-induktivnyy-m30-distantsiya-10-mm-trekhprovodnoy', '2600100001099', '08517002017000000', '1350310', false, 108000.00, 0.00, 36, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, 'ff528dc6-5c01-4819-af2b-2252f2a7dfb9', true, true, NULL);
INSERT INTO public.products VALUES ('86c06014-1c42-43fe-ab89-69d99701a509', '2025-12-09 05:37:54.726371+00', '2026-03-01 07:40:15.978665+00', 'b80b7dae-97c3-11eb-a7ce-68ecc5c3e82a', '1651', 'LJ8A3-2-Z/BY NO PNP 6-36VDC Датчик индуктивный M8 дистанция 2 мм трехпроводной', 'LJ8A3-2-Z/BY NO PNP 6-36VDC Датчик индуктивный M8 дистанция 2 мм трехпроводной', 'LJ8A3-2-Z/BY NO PNP 6-36VDC M8 induktiv sensorli, 2 mm masofali, uch simli datchik', '<p>LJ8A3-2-Z/BY NO PNP 6-36VDC Датчик индуктивный M8 дистанция 2 мм трехпроводной — это надежный промышленный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Он широко применяется в системах автоматизации для точного контроля наличия, положения и подсчета объектов. Датчик выполнен в резьбовом цилиндрическом корпусе M8 из прочного металлического материала, что обеспечивает легкую установку и высокую устойчивость к внешним воздействиям. Он работает в диапазоне напряжения 6-36В DC и имеет трехпроводное подключение, что упрощает интеграцию в различные автоматизированные линии. Это устройство гарантирует стабильную работу, долгий срок службы и высокую надежность в самых требовательных промышленных условиях.</p>', '<p>LJ8A3-2-Z/BY NO PNP 6-36VDC Датчик индуктивный M8 дистанция 2 мм трехпроводной — это надежный промышленный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Он широко применяется в системах автоматизации для точного контроля наличия, положения и подсчета объектов. Датчик выполнен в резьбовом цилиндрическом корпусе M8 из прочного металлического материала, что обеспечивает легкую установку и высокую устойчивость к внешним воздействиям. Он работает в диапазоне напряжения 6-36В DC и имеет трехпроводное подключение, что упрощает интеграцию в различные автоматизированные линии. Это устройство гарантирует стабильную работу, долгий срок службы и высокую надежность в самых требовательных промышленных условиях.</p>', 'LJ8A3-2-Z/BY NO PNP 6-36VDC induktiv M8 sensori 2 mm masofali uch simli - bu metall obyektlarni kontaktsiz aniqlash uchun mo‘ljallangan ishonchli sanoat datchigi. U avtomatlashtirish tizimlarida obyektlarning mavjudligini, holatini va sonini aniq nazorat qilish uchun keng qo‘llaniladi. Sensor mustahkam metall materialdan yasalgan M8 rezbali silindrsimon korpusga ega bo‘lib, bu uning oson o‘rnatilishini va tashqi ta’sirlarga yuqori chidamliligini ta’minlaydi. U 6-36V DC kuchlanish oralig‘ida ishlaydi va uch simli ulanishga ega, bu esa uni turli xil avtomatlashtirilgan liniyalarga oson integratsiya qilish imkonini beradi. Ushbu qurilma eng murakkab sanoat sharoitlarida ham barqaror ishlashni, uzoq muddat xizmat qilishni va yuqori ishonchlilikni kafolatlaydi.', 'lj8a3-2-zby-no-pnp-6-36vdc-datchik-induktivnyy-m8-distantsiya-2-mm-trekhprovodnoy', 'lj8a3-2-zby-no-pnp-6-36vdc-datchik-induktivnyy-m8-distantsiya-2-mm-trekhprovodnoy', 'lj8a3-2-zby-no-pnp-6-36vdc-m8-induktiv-sensorli-2-mm-masofali-uch-simli-datchik', '2600100000764', '08517002017000000', '1350310', false, 50300.00, 0.00, 276, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '07bcf492-09bf-4cef-b51a-dc4ada6ab677', true, true, NULL);
