INSERT INTO public.products VALUES ('554d0f97-172b-4a6e-abc9-7494b7653ee7', '2025-12-12 12:00:58.89737+00', '2026-03-01 07:40:14.688787+00', 'f32aa80a-b370-11ee-a12b-005056b88cb9', '4350', 'PR30-10DN NO NPN 10–30VDC Датчик индуктивный M30 дистанция 10 мм трехпроводной', 'PR30-10DN NO NPN 10–30VDC Датчик индуктивный M30 дистанция 10 мм трехпроводной', 'PR30-10DN NO NPN 10-30VDC induktiv sensor, M30 o‘lchamli, 10 mm masofaga mo‘ljallangan, uch simli', '<p>PR30-10DN NO NPN 10–30VDC Датчик индуктивный M30 дистанция 10 мм трехпроводной — это промышленный индуктивный датчик, предназначенный для бесконтактного и точного обнаружения металлических объектов. Этот датчик в цилиндрическом корпусе M30 способен работать на расстоянии до 10 мм, оснащен выходом типа NPN (NO) и имеет широкий диапазон рабочего напряжения 10-30 В постоянного тока. Его трехпроводное подключение обеспечивает простую интеграцию в системы автоматизации. Обладая высокой надежностью, прочностью и стабильностью работы, он является идеальным решением для применения на производственных линиях, конвейерах и в различных автоматизированных процессах для обнаружения присутствия и позиционирования объектов.</p>', '<p>PR30-10DN NO NPN 10–30VDC Датчик индуктивный M30 дистанция 10 мм трехпроводной — это промышленный индуктивный датчик, предназначенный для бесконтактного и точного обнаружения металлических объектов. Этот датчик в цилиндрическом корпусе M30 способен работать на расстоянии до 10 мм, оснащен выходом типа NPN (NO) и имеет широкий диапазон рабочего напряжения 10-30 В постоянного тока. Его трехпроводное подключение обеспечивает простую интеграцию в системы автоматизации. Обладая высокой надежностью, прочностью и стабильностью работы, он является идеальным решением для применения на производственных линиях, конвейерах и в различных автоматизированных процессах для обнаружения присутствия и позиционирования объектов.</p>', 'PR30-10DN NO NPN 10-30VDC induktiv datchik M30 10 mm masofali uch simli - bu metall obyektlarni kontaktsiz va aniq aniqlashga mo‘ljallangan sanoat induktiv datchigidir. M30 silindrik korpusli bu datchik 10 mm masofagacha ishlash qobiliyatiga ega bo‘lib, NPN (NO) turidagi chiqish bilan jihozlangan va 10-30 V o‘zgarmas tok keng ishchi kuchlanish diapazonida ishlaydi. Uning uch simli ulanishi avtomatlashtirish tizimlariga oson integratsiyalashuvni ta’minlaydi. Yuqori ishonchlilik, chidamlilik va ishlash barqarorligiga ega bo‘lgani sababli, u ishlab chiqarish liniyalarida, konveyerlarda va turli avtomatlashtirilgan jarayonlarda obyektlarning mavjudligini va joylashuvini aniqlash uchun ideal yechim hisoblanadi.', 'pr30-10dn-no-npn-10-30vdc-datchik-induktivnyy-m30-distantsiya-10-mm-trekhprovodnoy', 'pr30-10dn-no-npn-10-30vdc-datchik-induktivnyy-m30-distantsiya-10-mm-trekhprovodnoy', 'pr30-10dn-no-npn-10-30vdc-datchik-induktivnyy-m30-distantsiya-10-mm-trehprovodnoy', '2600100001082', '08517002017000000', '1350310', false, 108000.00, 0.00, 34, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, 'ff528dc6-5c01-4819-af2b-2252f2a7dfb9', true, true, NULL);
INSERT INTO public.products VALUES ('a0c01730-e657-4b20-9554-e24af60a9932', '2025-12-03 06:13:18.565408+00', '2026-03-01 07:40:16.814564+00', 'a37b1b30-3a3c-11ed-a7fd-f56a4477b039', '3135', 'NDR-240-12 MEAN WELL - блок питания, 12В, 10A, для монтажа на DIN-рейку', 'NDR-240-12 MEAN WELL - блок питания, 12В, 10A, для монтажа на DIN-рейку', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2600100006858', '08504003009000007', '1726381', false, 431000.00, 0.00, 38, 'pending', false, NULL, NULL, NULL, true, false, NULL);
INSERT INTO public.products VALUES ('b2adaff6-9b0c-4de7-b0e9-55a0b363947e', '2025-12-12 12:00:58.498473+00', '2026-03-01 07:40:14.649206+00', 'ea1ad8a2-b370-11ee-a12b-005056b88cb9', '4349', 'PR18-8AO NO 90-250VAC Датчик индуктивный M18 дистанция 8 мм двухпроводной', 'PR18-8AO NO 90-250VAC Датчик индуктивный M18 дистанция 8 мм двухпроводной', 'PR18-8AO NO 90-250VAC induktiv sensor, M18 o‘lchamli, 8 mm masofali, ikki simli', '<p>PR18-8AO NO 90-250VAC Датчик индуктивный M18 дистанция 8 мм двухпроводной — это надежный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Оснащенный цилиндрическим корпусом M18 с резьбой, он обеспечивает стабильное срабатывание на расстоянии до 8 мм, что делает его идеальным для широкого спектра промышленных задач. Двухпроводное подключение и рабочее напряжение 90-250VAC упрощают его интеграцию в существующие электрические схемы и системы автоматизации. Высокая надежность, долговечность и стабильность работы гарантируют длительную и бесперебойную эксплуатацию в автоматизированных производственных линиях, конвейерных системах и для точного определения положения различных компонентов. Легкость монтажа способствует быстрой настройке и снижению затрат на внедрение.</p>', '<p>PR18-8AO NO 90-250VAC Датчик индуктивный M18 дистанция 8 мм двухпроводной — это надежный индуктивный датчик, предназначенный для бесконтактного обнаружения металлических объектов. Оснащенный цилиндрическим корпусом M18 с резьбой, он обеспечивает стабильное срабатывание на расстоянии до 8 мм, что делает его идеальным для широкого спектра промышленных задач. Двухпроводное подключение и рабочее напряжение 90-250VAC упрощают его интеграцию в существующие электрические схемы и системы автоматизации. Высокая надежность, долговечность и стабильность работы гарантируют длительную и бесперебойную эксплуатацию в автоматизированных производственных линиях, конвейерных системах и для точного определения положения различных компонентов. Легкость монтажа способствует быстрой настройке и снижению затрат на внедрение.</p>', 'PR18-8AO NO 90-250VAC M18 induktiv datchigi 8 mm masofali ikki simli - bu metall obyektlarni kontaktsiz aniqlash uchun mo‘ljallangan ishonchli qurilma. Rezbali silindrsimon M18 korpusiga ega bo‘lib, 8 mm masofagacha barqaror ishlashni ta’minlaydi, shu bois u keng ko‘lamli sanoat vazifalari uchun ideal hisoblanadi. Ikki simli ulanish va 90-250VAC ishchi kuchlanish mavjud elektr sxemalar va avtomatlashtirish tizimlariga oson integratsiyalashuvini ta’minlaydi. Yuqori ishonchlilik, chidamlilik va ishlash barqarorligi avtomatlashtirilgan ishlab chiqarish liniyalarida, konveyer tizimlarida va turli xil komponentlarning aniq joylashuvini aniqlashda uzoq muddatli va uzluksiz ishlashni kafolatlaydi. O‘rnatishning osonligi tezkor sozlash va joriy etish xarajatlarini kamaytirishga yordam beradi.', 'pr18-8ao-no-90-250vac-datchik-induktivnyy-m18-distantsiya-8-mm-dvukhprovodnoy', 'pr18-8ao-no-90-250vac-datchik-induktivnyy-m18-distantsiya-8-mm-dvukhprovodnoy', 'pr18-8ao-no-90-250vac-datchik-induktivnyy-m18-distantsiya-8-mm-dvukhprovodnoy', '2600100001044', '08517002017000000', '1350310', false, 81100.00, 0.00, 78, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, 'a687b613-631f-4c34-9b97-cab3064eed92', true, true, NULL);
