INSERT INTO public.products VALUES ('dbf3a60a-6b9e-422f-bf68-acacf139bcbf', '2025-12-09 05:57:04.36589+00', '2026-03-01 07:40:14.3077+00', '1e118cab-b36f-11ee-a12b-005056b88cb9', '4338', 'LJ8A3-2-J/EZ NO 90-250VAC Датчик индуктивный M8 дистанция 2 мм двухпроводной', 'LJ8A3-2-J/EZ NO 90-250VAC Датчик индуктивный M8 дистанция 2 мм двухпроводной', 'LJ8A3-2-J/EZ NO 90-250VAC M8 induktiv datchigi, masofa 2 mm, ikki simli', '<p>LJ8A3-2-J/EZ NO 90-250VAC Датчик индуктивный M8 дистанция 2 мм двухпроводной — это двухпроводной индуктивный датчик в цилиндрическом корпусе M8, предназначенный для точного и надежного бесконтактного обнаружения металлических объектов. Его рабочая дистанция 2 мм и широкий диапазон напряжения 90-250 В переменного тока обеспечивают гибкость применения в различных промышленных условиях. Данный датчик легко интегрируется в системы автоматизации, на конвейерных линиях и для контроля положения металлических деталей. Высокая надежность, долговечность и стабильность работы гарантируют бесперебойность производственных процессов.</p>', '<p>LJ8A3-2-J/EZ NO 90-250VAC Датчик индуктивный M8 дистанция 2 мм двухпроводной — это двухпроводной индуктивный датчик в цилиндрическом корпусе M8, предназначенный для точного и надежного бесконтактного обнаружения металлических объектов. Его рабочая дистанция 2 мм и широкий диапазон напряжения 90-250 В переменного тока обеспечивают гибкость применения в различных промышленных условиях. Данный датчик легко интегрируется в системы автоматизации, на конвейерных линиях и для контроля положения металлических деталей. Высокая надежность, долговечность и стабильность работы гарантируют бесперебойность производственных процессов.</p>', 'LJ8A3-2-J/EZ NO 90-250VAC M8 induktiv datchigi, 2 mm masofali, ikki simli - bu M8 silindrik korpusli, ikki simli induktiv datchik bo‘lib, metall obyektlarni aniq va ishonchli tarzda kontaktsiz aniqlash uchun mo‘ljallangan. Uning 2 mm ishlash masofasi va 90-250 V o‘zgaruvchan tok kuchlanishining keng diapazoni turli sanoat sharoitlarida qo‘llash imkoniyatini beradi. Ushbu datchik avtomatlashtirish tizimlariga, konveyer liniyalariga va metall qismlar holatini nazorat qilishga osonlik bilan integratsiya qilinadi. Yuqori ishonchlilik, uzoq muddat xizmat qilish va ishlashdagi barqarorlik ishlab chiqarish jarayonlarining uzluksizligini kafolatlaydi.', 'inductive-proximity-sensor-m18', 'inductive-proximity-sensor-m18', 'inductive-proximity-sensor-m18', '2600100000726', '08517002017000000', '1350310', false, 75900.00, 0.00, 20, 'pending', false, 'f14f7f00-c044-45c7-af63-d2cf2d041b86', NULL, '07bcf492-09bf-4cef-b51a-dc4ada6ab677', true, true, NULL);
